"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[295],{8295:(e,i,t)=>{t.d(i,{tW:()=>s,C:()=>o,Y7:()=>a});let r={facebook:{label:"Facebook",emoji:"\uD83D\uDCD8"},tiktok:{label:"TikTok",emoji:"\uD83C\uDFB5"},telegram:{label:"Telegram",emoji:"✈️"},youtube:{label:"YouTube",emoji:"▶️"},instagram:{label:"Instagram",emoji:"\uD83D\uDCF8"},x:{label:"X (Twitter)",emoji:"\uD83D\uDC26"},linkedin:{label:"LinkedIn",emoji:"\uD83D\uDCBC"},whatsapp:{label:"WhatsApp",emoji:"\uD83D\uDCAC"},unknown:{label:"Website",emoji:"\uD83C\uDF10"}};function a(e){return r[function(e){try{let{hostname:i}=new URL(e);if(i.includes("tiktok.com"))return"tiktok";if(i.includes("youtube.com")||i.includes("youtu.be"))return"youtube";if(i.includes("instagram.com")||i.includes("instagr.am"))return"instagram";if(i.includes("facebook.com")||i.includes("fb.watch")||i.endsWith("fb.com"))return"facebook";if(i.includes("twitter.com")||i.includes("x.com"))return"x";if(i.includes("t.me")||i.includes("telegram.me")||i.includes("telegram.org"))return"telegram";if(i.includes("linkedin.com")||i.includes("lnkd.in"))return"linkedin";if(i.includes("whatsapp.com")||i.includes("wa.me"))return"whatsapp";return"unknown"}catch(e){return"unknown"}}(e)].emoji}function o(e,i){let t=function(e,i){let t=(null!=i?i:"").trim();if(!t)return"";let r=(null!=e?e:"").toLowerCase();return"tiktok"===r?/^https?:\/\/(vm|vt)\.tiktok\.com\//i.test(t)?t:t.replace(/^https?:\/\/(www\.)?tiktok\.com/i,"https://www.tiktok.com"):"facebook"===r?/^https?:\/\/(www\.)?(fb\.watch|fb\.com)\//i.test(t)?t:t.replace(/^https?:\/\/(www\.)?facebook\.com/i,"https://www.facebook.com"):"x"===r?t.replace(/^https?:\/\/(www\.)?twitter\.com/i,"https://x.com"):"instagram"===r?t.replace(/^https?:\/\/(www\.)?instagram\.com/i,"https://www.instagram.com"):"youtube"===r?t.replace(/^https?:\/\/(www\.)?youtube\.com/i,"https://www.youtube.com"):t}(e,i);(function(e){try{let i=new URL(e);return"http:"===i.protocol||"https:"===i.protocol}catch(e){return!1}})(t)&&window.open(t,"_blank","noopener,noreferrer")}let n={privacy:{key:"privacy",title:"Privacy Policy",badge:"GDPR & CCPA COMPLIANT",lastUpdated:"August 2026",blocks:[{t:"h",x:"1. Introduction & Overview"},{t:"p",x:'Welcome to View2Earn. View2Earn ("View2Earn," "we," "our," or "us") is committed to protecting your privacy and safeguarding your personal information. We believe that privacy is a fundamental part of building a secure, transparent, and trustworthy platform.'},{t:"p",x:'This Privacy Policy explains how we collect, use, store, protect, disclose, and process your personal information when you access or use the View2Earn website, mobile applications, and related services (collectively, the "Service").'},{t:"p",x:"Our goal is to collect only the information necessary to provide and improve the Service, maintain platform security, prevent fraud, comply with legal obligations, and deliver a reliable experience for all users."},{t:"p",x:"Please read this Privacy Policy carefully before using the Service. By accessing or using View2Earn, you acknowledge that you have read and understood this Privacy Policy. If you do not agree with this Privacy Policy, you should not access or use the Service."},{t:"p",x:"This Privacy Policy should be read together with our Terms of Service and any other policies that apply to your use of View2Earn."},{t:"h",x:"2. Information We Collect"},{t:"p",x:"View2Earn collects only the information necessary to provide, secure, improve, and operate the Service. The information we collect depends on how you interact with the Service and may include the following categories."},{t:"s",x:"2.1 Account Information"},{t:"p",x:"When you create an account, we may collect information such as your username or display name, your registered email address (where applicable), your selected blockchain ecosystem (such as Pi Network or Sidra Chain), your external user identifier or account identifier, your country or region, and your account creation date and account status."},{t:"s",x:"2.2 Activity Information"},{t:"p",x:"When you use the Service, we may collect information about your activities, including tasks completed, Reward Points earned/adjusted/redeemed/forfeited, referral relationships and activity, survey participation and completion status, quiz participation and results, reward redemption history, transaction records relating to eligible in-app rewards or supported wallet interactions, and fraud prevention and verification records."},{t:"s",x:"2.3 Device and Technical Information"},{t:"p",x:"To protect the Service against fraud, abuse, and unauthorized access, we may automatically collect limited technical information, including device type and operating system, browser type and version, device identifiers, IP address, general location derived from your IP address, language and time zone settings, network information, limited device fingerprinting signals (browser and hardware characteristics) used solely for fraud detection and platform security, and the Android Advertising ID (where permitted) for delivering personalized advertisements and measuring ad performance."},{t:"p",x:"We do not use device fingerprinting to track your browsing activity outside the View2Earn Service."},{t:"s",x:"2.4 Communications"},{t:"p",x:"If you contact View2Earn, submit a support request, apply for a partnership, or communicate with us, we may collect your name, email address, the content of your message, attachments you voluntarily provide, and records of our communications with you."},{t:"s",x:"2.5 Information from Third-Party Providers"},{t:"p",x:"Where permitted by applicable law and our agreements with third-party providers, we may receive limited information from trusted partners, including survey providers, advertising partners, authentication providers, analytics providers, and reward fulfillment providers. We collect only the information necessary to operate the Service, verify completed activities, prevent fraud, and provide eligible rewards."},{t:"s",x:"2.6 Information We Do Not Collect"},{t:"p",x:"To protect your privacy and security, View2Earn does not collect or store your Pi Network or Sidra Chain passphrase, seed phrase, or private keys, your wallet recovery phrases, your passwords for third-party services, personal messages exchanged on external platforms, your social media follower or friend counts for public display, or any information unrelated to providing or securing the Service."},{t:"p",x:"We are committed to collecting only the minimum amount of personal information reasonably necessary to operate, secure, and improve View2Earn."},{t:"h",x:"3. How We Use Your Information"},{t:"p",x:"View2Earn uses your personal information only for legitimate business purposes and only to the extent necessary to operate, improve, secure, and maintain the Service. We do not use your personal information for purposes that are incompatible with this Privacy Policy."},{t:"s",x:"3.1 To Provide the Service"},{t:"p",x:"We use your information to create and manage your account, authenticate your identity when you access the Service, process eligible activities/tasks/reward transactions, calculate/verify/manage Reward Points and reward redemptions, and provide access to features and services available on the platform."},{t:"s",x:"3.2 To Maintain Security and Prevent Fraud"},{t:"p",x:"We use your information to protect the Service, our users, advertisers, and partners by detecting fraudulent or suspicious activities, identifying multiple or unauthorized accounts, preventing bots/automated activity/abuse, monitoring unusual login attempts and security risks, investigating violations of our Terms of Service or other platform policies, and protecting the integrity of rewards, surveys, and promotional campaigns."},{t:"s",x:"3.3 To Improve the Service"},{t:"p",x:"We use information to analyze platform performance and reliability, improve user experience and platform functionality, fix technical issues/bugs/errors, develop new features/products/services, and measure the effectiveness of existing features."},{t:"s",x:"3.4 To Communicate with You"},{t:"p",x:"We may use your information to respond to your questions and support requests, send important account/security/service notifications, notify you about changes to our policies or Terms of Service, and provide updates relating to rewards, transactions, or platform operations. Where required by law, we will obtain your consent before sending promotional or marketing communications, and you may opt out at any time."},{t:"s",x:"3.5 To Comply with Legal Obligations"},{t:"p",x:"We may process your information where necessary to comply with applicable laws and regulations, respond to lawful requests from courts/regulators/government authorities, enforce our Terms of Service and other legal agreements, and protect the rights, safety, property, and security of View2Earn, our users, partners, and the public."},{t:"s",x:"3.6 To Support Business Operations"},{t:"p",x:"We may use information to administer partnerships and business relationships, perform internal audits/reporting/compliance activities, maintain accurate financial and operational records, and protect the long-term stability and integrity of the Service."},{t:"s",x:"3.7 What We Do Not Use Your Information For"},{t:"p",x:"View2Earn does not sell your personal information to third parties; does not use your information for unauthorized profiling or automated decision-making that produces legal or similarly significant effects without appropriate safeguards; does not access your private blockchain credentials, recovery phrases, or private keys; and does not use your information for purposes unrelated to providing, securing, or improving the Service without your consent, unless required by applicable law."},{t:"h",x:"4. Legal Basis for Processing"},{t:"p",x:"View2Earn processes personal information only when we have a valid legal basis to do so under applicable data protection laws. Depending on your location and how you use the Service, one or more of the following legal bases may apply."},{t:"s",x:"4.1 Performance of a Contract"},{t:"p",x:"We process your personal information when it is necessary to provide the Service you have requested or to fulfill our obligations under our Terms of Service, including creating/managing your account, verifying completed tasks and reward eligibility, processing Reward Points and redemptions, providing customer support, and maintaining your account and transaction history."},{t:"s",x:"4.2 Legitimate Interests"},{t:"p",x:"We may process personal information where it is reasonably necessary for our legitimate business interests, provided those interests do not override your fundamental rights and freedoms. These interests include protecting the Service from fraud/abuse/unauthorized access, maintaining platform security and system integrity, improving the performance/reliability/functionality of the Service, investigating suspected violations of our Terms of Service, and developing new products, features, and services."},{t:"s",x:"4.3 Compliance with Legal Obligations"},{t:"p",x:"We may process personal information where required to comply with applicable laws, regulations, court orders, or lawful requests from governmental or regulatory authorities, including maintaining records, responding to legal requests, preventing unlawful activity, and meeting regulatory compliance requirements."},{t:"s",x:"4.4 Consent"},{t:"p",x:"Where required by applicable law, we will request your consent before processing your personal information for specific purposes, such as certain marketing communications or optional features. You may withdraw your consent at any time; withdrawal does not affect the lawfulness of processing carried out before consent was withdrawn."},{t:"s",x:"4.5 Protection of Rights and Safety"},{t:"p",x:"Where permitted by applicable law, we may process personal information when necessary to protect the rights, property, security, or safety of View2Earn, our users, our business partners, advertisers and service providers, or the general public. This may include investigating security incidents, preventing fraud, responding to emergencies, or protecting the integrity of the Service."},{t:"h",x:"5. How We Share Your Information"},{t:"p",x:"View2Earn respects your privacy and shares your personal information only when necessary to operate the Service, comply with legal obligations, protect our users, or support legitimate business operations. We do not sell, rent, or trade your personal information to third parties for their own marketing purposes."},{t:"s",x:"5.1 Service Providers"},{t:"p",x:"We may share limited personal information with trusted third-party service providers that help us operate and maintain the Service, including providers of cloud hosting/infrastructure, user authentication/account security, customer support, analytics/performance monitoring, email/communication services, reward fulfillment/payment processing, and fraud prevention/platform security. These providers may access personal information only as necessary to perform services on our behalf and are required to protect your information."},{t:"s",x:"5.2 Advertising and Reward Partners"},{t:"p",x:"Where necessary to provide eligible tasks, surveys, advertisements, or rewards, we may share limited information with trusted advertising networks, survey providers, and reward partners. Only the minimum information necessary to verify participation, prevent fraud, confirm eligibility, or process rewards will be shared."},{t:"s",x:"5.3 Legal Requirements"},{t:"p",x:"We may disclose personal information if we believe, in good faith, that disclosure is necessary to comply with applicable laws or legal obligations, respond to lawful requests from courts/regulators/government authorities, enforce our Terms of Service or other legal agreements, investigate suspected fraud/abuse/illegal activity, or protect the rights, safety, property, or security of View2Earn, our users, business partners, or the public."},{t:"s",x:"5.4 Business Transfers"},{t:"p",x:"If View2Earn is involved in a merger, acquisition, financing, reorganization, sale of assets, or other business transaction, your personal information may be transferred as part of that transaction, subject to applicable legal and confidentiality obligations. Where required by law, we will provide appropriate notice before such a transfer becomes effective."},{t:"s",x:"5.5 With Your Consent"},{t:"p",x:"We may share your personal information with other parties when you have given us your explicit consent or when you request or authorize us to do so. You may withdraw your consent at any time where consent is the legal basis for the sharing."},{t:"s",x:"5.6 What We Do Not Share"},{t:"p",x:"View2Earn does not sell your personal information to third parties; does not share your blockchain wallet recovery phrase, private keys, or secret passphrase; does not share more personal information than is reasonably necessary for the purpose for which it is disclosed; and does not allow third parties to use your personal information for unrelated marketing purposes without your consent."},{t:"h",x:"6. Cookies and Similar Technologies"},{t:"p",x:"View2Earn uses cookies and similar technologies to improve your experience, maintain platform security, analyze performance, and ensure the reliable operation of the Service. Cookies are small text files stored on your device when you visit our website. Similar technologies, such as local storage, web beacons, pixels, and software development kits (SDKs), may also be used in our website and mobile applications for similar purposes."},{t:"s",x:"6.1 Types of Cookies We Use"},{t:"p",x:"Essential Cookies are necessary for the operation of the Service and cannot be disabled without affecting core functionality. They help us authenticate users, maintain secure login sessions, protect against fraud and unauthorized access, and remember essential security settings."},{t:"p",x:"Performance and Analytics Cookies help us understand how users interact with the Service by collecting anonymous or aggregated information, including pages visited, feature usage, error reports, performance metrics, and device/browser compatibility."},{t:"p",x:"Functional Cookies remember your preferences to provide a more personalized experience, such as language preferences, theme/display settings, session preferences, and other user-selected settings."},{t:"p",x:"Security Technologies may be used as part of our fraud prevention and security systems to detect suspicious or automated activity, prevent multiple-account abuse, protect advertiser and reward campaigns, and maintain the integrity of the Service."},{t:"s",x:"6.2 Managing Cookies"},{t:"p",x:"Most web browsers allow you to control or disable cookies through your browser settings. Please note that disabling certain cookies may limit your ability to access or use some features of the Service. Mobile applications may use technologies that function similarly to cookies; these can generally be managed through your device settings where available."},{t:"s",x:"6.3 Third-Party Technologies"},{t:"p",x:"Some trusted third-party providers integrated with the Service, such as analytics providers, authentication providers, advertising partners, and reward providers, may use their own cookies or similar technologies in accordance with their respective privacy policies. View2Earn does not control the cookies or technologies used directly by third-party providers."},{t:"s",x:"6.4 Future Updates"},{t:"p",x:"As View2Earn continues to grow, we may introduce additional technologies to improve security, functionality, and user experience. Where required by applicable law, we will provide appropriate notice or request your consent before using non-essential cookies or similar technologies. For more detailed information, please refer to our separate Cookie Policy, where available."},{t:"h",x:"7. Data Retention"},{t:"p",x:"View2Earn retains personal information only for as long as necessary to fulfill the purposes described in this Privacy Policy, comply with legal obligations, resolve disputes, enforce our agreements, and protect the security and integrity of the Service."},{t:"s",x:"7.1 Retention Period"},{t:"p",x:"The length of time we retain personal information depends on the type of information and the purpose for which it was collected. We consider factors such as the nature of the information, the purpose for which it was collected, legal and regulatory requirements, fraud prevention and security needs, and legitimate business and operational requirements."},{t:"s",x:"7.2 Account Information"},{t:"p",x:"We retain account information for as long as your account remains active and for a reasonable period afterward where necessary to maintain account records, resolve disputes, prevent fraud and abuse, comply with applicable legal obligations, and enforce our Terms of Service and other platform policies."},{t:"s",x:"7.3 Activity and Transaction Records"},{t:"p",x:"Information relating to completed tasks, Reward Points, reward redemptions, referrals, surveys, and transaction history may be retained for recordkeeping, auditing, fraud prevention, financial reporting, and compliance purposes."},{t:"s",x:"7.4 Security and Fraud Prevention Records"},{t:"p",x:"Security logs, device information, IP addresses, and fraud detection records may be retained for an appropriate period to investigate suspicious activities, detect repeated fraudulent behavior, protect the Service and our users, and support legal or regulatory investigations where required."},{t:"s",x:"7.5 Deletion of Information"},{t:"p",x:"When personal information is no longer required for the purposes described in this Privacy Policy, we will take reasonable steps to securely delete, anonymize, or permanently destroy the information, unless a longer retention period is required or permitted by applicable law."},{t:"s",x:"7.6 Account Deletion Requests"},{t:"p",x:"You may request the deletion of your personal information or closure of your account by contacting View2Earn using the contact details provided in this Privacy Policy. Please note that we may retain certain information after account deletion where necessary to comply with legal obligations, resolve disputes, prevent fraud and abuse, protect the rights/property/security of View2Earn, our users, and business partners, or enforce our legal agreements."},{t:"s",x:"7.7 Anonymized Information"},{t:"p",x:"View2Earn may retain information that has been anonymized or aggregated so that it can no longer reasonably identify an individual user. Such information may be used for analytics, research, platform improvement, security, and business reporting."},{t:"h",x:"8. Your Privacy Rights"},{t:"p",x:"View2Earn respects your privacy and is committed to providing you with appropriate control over your personal information. Depending on your location and applicable law, you may have some or all of the following rights."},{t:"s",x:"8.1 Right to Access"},{t:"p",x:"You may request confirmation of whether View2Earn processes your personal information and, where applicable, request access to the personal information we hold about you."},{t:"s",x:"8.2 Right to Correct Information"},{t:"p",x:"If you believe that any personal information we hold about you is inaccurate, incomplete, or outdated, you may request that we correct or update it."},{t:"s",x:"8.3 Right to Request Deletion"},{t:"p",x:"You may request the deletion of your personal information where permitted by applicable law. Please note that we may retain certain information where necessary to comply with legal obligations, resolve disputes, prevent fraud and abuse, protect the security and integrity of the Service, or enforce our Terms of Service and other legal agreements."},{t:"s",x:"8.4 Right to Withdraw Consent"},{t:"p",x:"Where we process your personal information based on your consent, you may withdraw that consent at any time. Withdrawing consent will not affect the lawfulness of any processing carried out before your consent was withdrawn."},{t:"s",x:"8.5 Right to Object or Restrict Processing"},{t:"p",x:"Where permitted by applicable law, you may object to or request that we restrict certain processing of your personal information. We will carefully consider such requests in accordance with applicable legal requirements."},{t:"s",x:"8.6 Right to Data Portability"},{t:"p",x:"Where applicable, you may request a copy of certain personal information you have provided to View2Earn in a structured, commonly used, and machine-readable format. Where technically feasible and legally permitted, you may also request that such information be transferred to another service provider."},{t:"s",x:"8.7 Exercising Your Rights"},{t:"p",x:"To exercise any of your privacy rights, please contact View2Earn using the contact information provided at the end of this Privacy Policy. To protect your privacy and the security of your account, we may ask you to verify your identity before processing your request. We will respond to privacy requests within a reasonable period and in accordance with applicable law."},{t:"s",x:"8.8 No Discrimination"},{t:"p",x:"View2Earn will not unfairly deny access to the Service or discriminate against users solely because they choose to exercise their privacy rights, except where certain information is required to provide the Service or where otherwise permitted by applicable law."},{t:"h",x:"9. Data Security"},{t:"p",x:"View2Earn is committed to protecting your personal information through appropriate technical, administrative, and organizational security measures designed to prevent unauthorized access, disclosure, alteration, loss, misuse, or destruction of personal information. While no method of electronic transmission or storage is completely secure, we continuously work to maintain and improve the security of our systems and services."},{t:"s",x:"9.1 Security Measures"},{t:"p",x:"View2Earn implements reasonable security measures, which may include encryption of sensitive data during transmission where appropriate, secure authentication and account protection mechanisms, access controls to limit access to authorized personnel only, continuous monitoring of systems for suspicious or unauthorized activities, fraud detection and prevention technologies, regular security updates/maintenance/system improvements, and secure backup and disaster recovery procedures."},{t:"s",x:"9.2 User Responsibilities"},{t:"p",x:"Users also play an important role in protecting their accounts. You are responsible for keeping your account credentials confidential, choosing a strong and unique password, enabling additional security features such as multi-factor authentication where available, promptly notifying View2Earn if you suspect unauthorized access to your account, and protecting your devices against unauthorized access."},{t:"s",x:"9.3 Security Incidents"},{t:"p",x:"If View2Earn becomes aware of a security incident that may affect your personal information, we will investigate the incident promptly and take appropriate steps to contain, assess, and address the issue. Where required by applicable law, we will notify affected users and relevant authorities within the legally required timeframe."},{t:"s",x:"9.4 Third-Party Security"},{t:"p",x:"Some features of the Service rely on trusted third-party providers. While we carefully select service providers that support appropriate security standards, View2Earn is not responsible for the independent security practices of third-party services that operate outside our control."},{t:"s",x:"9.5 No Absolute Security Guarantee"},{t:"p",x:"Although View2Earn applies reasonable safeguards to protect personal information, no internet-based service, computer system, or method of electronic storage can be guaranteed to be completely secure. For this reason, we cannot guarantee absolute security, and users should take appropriate precautions to protect their own accounts and personal information."},{t:"h",x:"10. International Data Transfers"},{t:"p",x:"View2Earn may operate internationally and work with trusted service providers located in different countries. As a result, your personal information may be transferred to, processed, or stored in countries other than the country where you reside. We are committed to ensuring that any international transfer of personal information is carried out responsibly and in accordance with applicable data protection laws."},{t:"s",x:"10.1 International Operations"},{t:"p",x:"By using the Service, you understand that your personal information may be processed in countries where View2Earn, its affiliates, or its trusted service providers operate. These countries may have data protection laws that differ from those in your country of residence."},{t:"s",x:"10.2 Safeguards"},{t:"p",x:"Where personal information is transferred internationally, View2Earn will take reasonable steps to protect your information by implementing appropriate safeguards, which may include entering into contractual agreements with service providers that require appropriate privacy and security protections, working only with trusted providers, applying internal policies and procedures, and implementing additional safeguards where required by applicable law."},{t:"s",x:"10.3 Data Protection Standards"},{t:"p",x:"Regardless of where your personal information is processed, View2Earn is committed to handling your information in a manner consistent with this Privacy Policy and applicable legal requirements. We require our trusted service providers to process personal information only for authorized purposes and to maintain appropriate confidentiality and security measures."},{t:"s",x:"10.4 Your Rights"},{t:"p",x:"Where applicable law provides additional rights relating to international data transfers, View2Earn will respect those rights and provide reasonable assistance to help you exercise them. You may contact us using the contact information provided in this Privacy Policy if you have questions about how your personal information is transferred or protected."},{t:"h",x:"11. Children's Privacy"},{t:"p",x:"View2Earn is intended only for individuals who are at least 18 years of age or the minimum age required to enter into a legally binding agreement under the laws of their jurisdiction, whichever is higher. We do not knowingly collect, use, or disclose personal information from children under the age of 18."},{t:"p",x:"If we become aware that we have collected personal information from a child under the applicable minimum age without appropriate legal authorization, we will take reasonable steps to delete the information as soon as practicable, unless we are required by applicable law to retain it."},{t:"p",x:"Parents, guardians, or legal representatives who believe that a child has provided personal information to View2Earn without authorization may contact us using the contact details provided in this Privacy Policy. We will promptly investigate the request and, where appropriate, remove the relevant information."},{t:"h",x:"12. Third-Party Services"},{t:"p",x:"View2Earn integrates with trusted third-party services to provide certain features, improve the user experience, maintain platform security, and support the operation of the Service. These third-party providers operate independently and may have their own privacy policies, terms of service, and data handling practices. We encourage you to review their policies before using their services."},{t:"s",x:"12.1 Third-Party Providers"},{t:"p",x:"The Service may integrate with or rely on third-party providers, including but not limited to survey and market research providers, advertising and reward partners, authentication and identity verification providers, cloud hosting and infrastructure providers, analytics and performance monitoring services, email and communication service providers, blockchain networks and related service providers, and payment/reward fulfillment or other operational service providers."},{t:"s",x:"12.2 Information Shared with Third Parties"},{t:"p",x:"Where necessary, View2Earn may share limited personal information with trusted third-party providers solely for purposes such as providing and maintaining the Service, verifying task completion and reward eligibility, preventing fraud/abuse/unauthorized activity, processing rewards and other eligible transactions, improving platform performance and security, and complying with legal and regulatory obligations. We share only the minimum amount of information reasonably necessary for these purposes."},{t:"s",x:"12.3 Third-Party Privacy Practices"},{t:"p",x:"Third-party providers are responsible for their own collection, processing, storage, and protection of personal information. View2Earn does not control the privacy practices, policies, or security measures of independent third-party services. Your interactions with those services are governed by their own terms and privacy policies."},{t:"s",x:"12.4 External Links"},{t:"p",x:"The Service may contain links to websites, applications, or services operated by third parties. View2Earn is not responsible for the content, availability, privacy practices, or security of external websites or services. Accessing third-party services is at your own discretion and risk."},{t:"s",x:"12.5 Blockchain Networks"},{t:"p",x:"View2Earn may support features that interact with independent blockchain ecosystems, including Pi Network and Sidra Chain. These blockchain networks operate independently of View2Earn and maintain their own governance, technical infrastructure, privacy practices, and terms of use. View2Earn does not control the operation, availability, security, or policies of any blockchain network and is not responsible for actions or decisions taken by their operators."},{t:"s",x:"12.6 Future Integrations"},{t:"p",x:"As the Service evolves, View2Earn may integrate with additional trusted third-party providers to improve functionality, enhance security, introduce new features, or expand available services. Any new integrations involving the processing of personal information will be implemented in accordance with this Privacy Policy and applicable data protection laws."},{t:"h",x:"13. Changes to This Privacy Policy"},{t:"p",x:"View2Earn may update this Privacy Policy from time to time to reflect changes in our Services, business operations, legal obligations, security practices, technologies, or the way we process personal information. We are committed to maintaining transparency and will make reasonable efforts to keep users informed of significant changes."},{t:"s",x:"13.1 Reasons for Updates"},{t:"p",x:"We may revise this Privacy Policy for reasons including, but not limited to, introducing new features/products/services, improving platform security and fraud prevention, complying with new laws/regulations/legal requirements, reflecting changes in our business operations or partnerships, updating our data processing practices, and clarifying existing provisions to improve transparency and readability."},{t:"s",x:"13.2 Notification of Changes"},{t:"p",x:"When we make material changes to this Privacy Policy, we may notify users through one or more of the following methods: publishing the updated Privacy Policy on the View2Earn website or mobile application, displaying an in-app notification, sending an email to the registered email address associated with your account (where appropriate), or using any other communication method that we reasonably consider appropriate."},{t:"p",x:"Minor editorial, formatting, or administrative changes that do not materially affect your privacy rights may be made without individual notice."},{t:"s",x:"13.3 Effective Date"},{t:"p",x:'The most current version of this Privacy Policy will always display a "Last Updated" date at the top of the document. Unless otherwise required by applicable law, updates become effective upon publication. Where required by law or where changes materially affect your privacy rights, we may provide advance notice before the updated Privacy Policy becomes effective.'},{t:"s",x:"13.4 Continued Use of the Service"},{t:"p",x:"By continuing to access or use the Service after an updated Privacy Policy becomes effective, you acknowledge that you have been informed of the revised Policy. Where your consent is required by applicable law for new processing activities, View2Earn will obtain your consent before carrying out those activities. If you do not agree with the updated Privacy Policy, you should stop using the Service and may request the deletion of your personal information or closure of your account."},{t:"h",x:"14. Contact Information"},{t:"p",x:"View2Earn values your privacy and welcomes your questions, concerns, and requests regarding this Privacy Policy or our data processing practices. If you wish to contact us, please use the appropriate communication channel below."},{t:"l",x:["Privacy Inquiries: privacy@view2earn.org","Data Protection Requests: privacy@view2earn.org","General Support: support@view2earn.org","Security & Vulnerability Reports: security@view2earn.org","Business Partnerships: partners@view2earn.org","Legal Inquiries: legal@view2earn.org"]},{t:"p",x:"View2Earn will make reasonable efforts to acknowledge and respond to legitimate privacy and data protection requests within a reasonable period and in accordance with applicable law. Some requests may require additional time where they are particularly complex or where additional identity verification is necessary."},{t:"p",x:"Official communications from View2Earn regarding privacy or data protection will be sent only through our official website, mobile application, or email addresses ending with @view2earn.org. Users should be cautious of emails or messages claiming to represent View2Earn from unofficial sources. View2Earn is not responsible for communications originating from unauthorized third parties or fraudulent impersonators."}]},cookies:{key:"cookies",title:"Cookie Policy",badge:"COOKIES & SIMILAR TECHNOLOGIES",lastUpdated:"August 2026",blocks:[{t:"h",x:"1. Introduction"},{t:"p",x:'Welcome to View2Earn. This Cookie Policy explains how View2Earn ("View2Earn," "we," "our," or "us") uses cookies and similar technologies when you access or use our website, mobile applications, and related services (collectively, the "Service").'},{t:"p",x:"This Policy should be read together with our Privacy Policy and Terms of Service."},{t:"p",x:"By continuing to use the Service, you acknowledge that cookies and similar technologies may be used as described in this Policy, subject to your preferences and applicable law."},{t:"h",x:"2. What Are Cookies?"},{t:"p",x:"Cookies are small text files stored on your device when you visit a website. They help websites remember information about your visit, improve performance, enhance security, and provide a better user experience."},{t:"p",x:'In addition to cookies, View2Earn may use similar technologies, including Local Storage, Session Storage, Web Beacons, Pixels, Software Development Kits (SDKs), and Device identifiers. These technologies perform similar functions and are collectively referred to as "Cookies" in this Policy unless otherwise stated.'},{t:"h",x:"3. Why We Use Cookies"},{t:"p",x:"View2Earn uses cookies and similar technologies to operate and maintain the Service, authenticate users and maintain secure login sessions, protect against fraud and abuse, remember user preferences, improve performance, analyze usage patterns, support rewards and advertising campaigns, measure feature effectiveness, and comply with legal requirements."},{t:"p",x:"We do not use cookies to collect more personal information than is reasonably necessary for these purposes."},{t:"h",x:"4. Types of Cookies We Use"},{t:"s",x:"4.1 Essential Cookies"},{t:"p",x:"Essential cookies are necessary for the operation of the Service. They enable user authentication, secure login sessions, account protection, fraud prevention, system security, load balancing, and basic website functionality. These cookies cannot be disabled without affecting core features of the Service."},{t:"s",x:"4.2 Functional Cookies"},{t:"p",x:"Functional cookies remember your preferences, including language selection, theme preferences, accessibility settings, region or country preferences, and other personalization settings."},{t:"s",x:"4.3 Analytics Cookies"},{t:"p",x:"Analytics cookies help us understand how users interact with the Service by collecting information such as pages visited, feature usage, navigation patterns, performance statistics, error reports, and device compatibility. Where possible, analytics information is aggregated or anonymized."},{t:"s",x:"4.4 Security Cookies"},{t:"p",x:"Security cookies help View2Earn detect suspicious activity, prevent unauthorized access, identify multiple-account abuse, detect bots and automated traffic, protect advertiser and reward campaigns, and maintain platform integrity."},{t:"s",x:"4.5 Third-Party Cookies"},{t:"p",x:"Some trusted third-party providers integrated with the Service may place or access their own cookies in accordance with their respective privacy policies. These providers may include analytics providers, authentication providers, advertising partners, survey providers, and cloud infrastructure providers. View2Earn does not control third-party cookies."},{t:"s",x:"4.6 Cookies Used on This Website"},{t:"p",x:"The View2Earn website sets the following first-party cookies. Consent cookies are stored as soon as you make a choice in the cookie banner; analytics cookies are only set once you accept the banner."},{t:"l",x:["v2e_consent — records whether you accepted or rejected non-essential cookies. Essential; always set after you respond to the cookie banner. Expires after 1 year.","v2e_vid — an anonymous, randomly generated visitor identifier used to count unique visitors. Analytics; set only with your consent. Expires after 1 year.","v2e_visits — the number of times you have visited the website, used to distinguish new from returning visitors. Analytics; set only with your consent. Expires after 1 year.","v2e_first_visit — the date and time of your first visit to the website. Analytics; set only with your consent. Expires after 1 year.","v2e_last_visit — the date and time of your most recent visit to the website. Analytics; set only with your consent. Expires after 1 year.","v2e_last_page — the last page you visited on the website, used to understand navigation patterns. Analytics; set only with your consent. Expires after 1 day."]},{t:"h",x:"5. Managing Cookies"},{t:"p",x:"Most web browsers allow you to view stored cookies, delete cookies, block cookies, limit third-party cookies, and receive notifications before cookies are stored."},{t:"p",x:"Please note that disabling certain cookies may reduce the functionality, security, or performance of the Service. Mobile applications may use technologies similar to cookies that can often be managed through your device settings."},{t:"h",x:"6. Third-Party Technologies"},{t:"p",x:"View2Earn may use trusted third-party services to help operate the Service. These providers may use cookies or similar technologies in accordance with their own privacy policies. We encourage users to review the privacy policies of any third-party services they interact with through the Service."},{t:"h",x:"7. Changes to This Cookie Policy"},{t:"p",x:'View2Earn may update this Cookie Policy from time to time to reflect changes in technology, legal requirements, business operations, or our use of cookies. The latest version will always display a "Last Updated" date. Where required by applicable law, we will provide appropriate notice before material changes become effective.'},{t:"h",x:"8. Your Choices"},{t:"p",x:"You may manage your cookie preferences at any time through your browser settings, your device settings, or cookie preference tools made available through the Service, where applicable."},{t:"p",x:"Please note that rejecting certain cookies may affect your ability to use some features of the Service."},{t:"h",x:"9. Related Policies"},{t:"p",x:"This Cookie Policy should be read together with the Privacy Policy and Terms of Service. These documents work together to explain how View2Earn collects, processes, protects, and manages your information."},{t:"h",x:"10. Contact Information"},{t:"p",x:"If you have questions about this Cookie Policy or our use of cookies and similar technologies, please contact us:"},{t:"l",x:["Privacy Team: privacy@view2earn.org","General Support: support@view2earn.org","Security Concerns: security@view2earn.org"]}]},"anti-fraud":{key:"anti-fraud",title:"Anti-Fraud Policy",badge:"ZERO-TOLERANCE FRAUD PREVENTION",lastUpdated:"August 2026",blocks:[{t:"h",x:"1. Introduction"},{t:"p",x:'Welcome to View2Earn. View2Earn ("View2Earn," "we," "our," or "us") is committed to maintaining a fair, secure, and trustworthy rewards platform for all users, advertisers, survey providers, partners, and other stakeholders.'},{t:"p",x:"Fraud, abuse, and dishonest activities undermine the integrity of the Service, reduce opportunities for legitimate users, and may cause financial losses to our partners. For this reason, View2Earn maintains a zero-tolerance approach toward fraudulent or deceptive conduct."},{t:"p",x:"This Anti-Fraud Policy explains the standards of conduct expected from all users, the types of activities that are prohibited, how suspicious activities may be investigated, and the actions View2Earn may take to protect the integrity of the Service."},{t:"p",x:"This Policy applies to all users of the View2Earn website, mobile applications, and related services, regardless of their location or the blockchain ecosystem they use."},{t:"p",x:"By creating an account or using the Service, you agree to comply with this Anti-Fraud Policy, our Terms of Service, Privacy Policy, and all other applicable platform policies."},{t:"p",x:"Failure to comply with this Policy may result in warnings, reward forfeiture, account suspension, permanent account termination, or other actions permitted by applicable law."},{t:"h",x:"2. Purpose of the Policy"},{t:"p",x:"The purpose of this Anti-Fraud Policy is to protect the integrity, security, and fairness of the View2Earn platform by preventing, detecting, investigating, and responding to fraudulent, deceptive, or abusive activities."},{t:"p",x:"Specifically, this Policy is intended to protect legitimate users from unfair competition and fraudulent activities; safeguard advertisers, survey providers, and business partners from invalid traffic, fake engagements, and reward abuse; prevent multiple-account abuse, identity fraud, automated activity, and other forms of platform manipulation; preserve the accuracy and integrity of Reward Points, referrals, surveys, advertisements, and promotional campaigns; promote transparency, accountability, and ethical conduct; support compliance with applicable laws and industry standards; and protect the reputation, reliability, and long-term sustainability of the View2Earn platform."},{t:"p",x:"This Policy applies equally to all users, regardless of their location, account type, referral status, blockchain ecosystem, or level of activity. No user, partner, or participant is exempt from the standards set out in this Policy."},{t:"p",x:"View2Earn reserves the right to investigate suspected fraudulent or abusive conduct and to take appropriate action whenever necessary to protect the Service, its users, and its business partners."},{t:"h",x:"3. Prohibited Activities"},{t:"p",x:"To protect the integrity, fairness, and security of the Service, users must not engage in any fraudulent, deceptive, abusive, or dishonest activity. The following activities are strictly prohibited. This list is intended to provide examples and is not exhaustive. View2Earn reserves the right to determine whether any conduct violates this Policy."},{t:"s",x:"3.1 Multiple Accounts"},{t:"p",x:"Users must not create, own, control, or operate more than one account unless expressly authorized by View2Earn in writing. This includes creating additional accounts using different email addresses, devices, phone numbers, wallets, identities, or any other method intended to bypass platform restrictions."},{t:"s",x:"3.2 Identity Misrepresentation"},{t:"p",x:"Users must not impersonate another person or organization, provide false/misleading/stolen identity information, use another person's account without authorization, or misrepresent their eligibility to participate in tasks, surveys, or promotional campaigns."},{t:"s",x:"3.3 Automated Activity"},{t:"p",x:"The use of bots, scripts, automation tools, click farms, artificial intelligence systems, browser automation, emulators, macros, or any other technology designed to automate participation or manipulate the Service is strictly prohibited unless expressly authorized by View2Earn."},{t:"s",x:"3.4 Fraudulent Task Completion"},{t:"p",x:"Users must not submit false or misleading evidence of task completion, upload edited/manipulated/fabricated screenshots, falsify survey responses, complete tasks without meeting the stated requirements, or attempt to obtain rewards through deception."},{t:"s",x:"3.5 Reward Manipulation"},{t:"p",x:"Users must not attempt to obtain Reward Points or rewards through dishonest means, including exploiting software bugs or vulnerabilities, manipulating referrals or promotional campaigns, artificially increasing engagement metrics, circumventing reward eligibility requirements, or attempting duplicate reward claims."},{t:"s",x:"3.6 Referral Abuse"},{t:"p",x:"Users must not create fake referral accounts, refer themselves using multiple accounts, purchase or sell referrals, use automated systems to generate referrals, or manipulate referral rewards through fraudulent activity."},{t:"s",x:"3.7 Survey and Advertising Fraud"},{t:"p",x:"Users must not submit dishonest or inconsistent survey responses, attempt surveys intended for users who do not meet the eligibility criteria, use VPNs/proxies/virtual machines or other methods to disguise their true location where prohibited, interfere with advertisers' campaigns or survey providers' systems, or generate invalid traffic, fake impressions, or artificial engagement."},{t:"s",x:"3.8 Platform Abuse"},{t:"p",x:"Users must not attempt to interfere with the normal operation of the Service, reverse engineer/exploit/test platform vulnerabilities without authorization, introduce malware/viruses or other harmful software, launch denial-of-service attacks or similar disruptive activities, or circumvent security measures or access controls."},{t:"s",x:"3.9 Account Trading and Unauthorized Transfers"},{t:"p",x:"Unless expressly permitted by View2Earn, users may not buy, sell, rent, lease, or transfer accounts, share accounts with other individuals, or allow unauthorized persons to access their accounts. Account holders remain responsible for all activity occurring under their accounts."},{t:"s",x:"3.10 Abuse of Blockchain Ecosystems"},{t:"p",x:"Users must not use the Service to engage in fraudulent or deceptive activities involving supported blockchain ecosystems, including Pi Network, Sidra Chain, or any future supported ecosystem. View2Earn does not permit any activity that violates the rules, policies, or integrity of those independent ecosystems."},{t:"s",x:"3.11 Circumvention of Platform Controls"},{t:"p",x:"Users must not attempt to bypass fraud detection systems, eligibility requirements, account restrictions, security measures, verification procedures, or enforcement actions implemented by View2Earn."},{t:"s",x:"3.12 Any Other Fraudulent Conduct"},{t:"p",x:"Any activity that View2Earn reasonably determines to be fraudulent, deceptive, abusive, unethical, or harmful to the Service, its users, advertisers, survey providers, business partners, or the broader ecosystem may be treated as a violation of this Policy, even if it is not specifically listed above."},{t:"h",x:"4. Fraud Detection and Monitoring"},{t:"p",x:"View2Earn actively monitors the Service to detect, prevent, investigate, and respond to fraudulent, deceptive, abusive, or unauthorized activities. Our fraud detection systems are designed to protect legitimate users, advertisers, survey providers, business partners, and the integrity of the View2Earn platform. Monitoring is conducted in accordance with our Privacy Policy, applicable laws, and our commitment to protecting user privacy."},{t:"s",x:"4.1 Fraud Detection Methods"},{t:"p",x:"View2Earn may use automated systems, manual reviews, and other reasonable security measures to identify suspicious activities, including multiple-account detection, device and network analysis, login and authentication monitoring, unusual account or reward activity, referral pattern analysis, survey and task verification, risk scoring and behavioral analysis, and security event logging and monitoring."},{t:"s",x:"4.2 Risk Assessment"},{t:"p",x:"View2Earn may evaluate account activity to determine whether it presents an elevated risk to the platform. Risk indicators may include unusual activity patterns, inconsistent information, repeated policy violations, or other behaviors reasonably associated with fraudulent conduct. A higher risk assessment does not automatically mean that fraud has occurred; additional review may be conducted before any enforcement action is taken."},{t:"s",x:"4.3 Manual Review"},{t:"p",x:"Certain activities may be reviewed by authorized members of the View2Earn team to verify compliance with this Policy. Manual reviews may include verification of submitted evidence, review of account history, investigation of reported violations, confirmation of reward eligibility, and examination of suspicious transactions or activities."},{t:"s",x:"4.4 Temporary Restrictions"},{t:"p",x:"Where suspicious activity is detected, View2Earn may temporarily restrict certain account features while an investigation is conducted. Such restrictions may include temporary suspension of reward redemptions, delayed processing of rewards, additional identity or account verification, temporary account limitations, or temporary suspension of specific platform features. These measures are intended to protect both users and the integrity of the Service and do not necessarily indicate that a policy violation has been confirmed."},{t:"s",x:"4.5 Cooperation with Service Providers"},{t:"p",x:"Where necessary, View2Earn may work with trusted service providers, advertisers, survey providers, security partners, and fraud prevention services to verify suspicious activities and protect the platform. Information shared for fraud prevention purposes will be limited to what is reasonably necessary and handled in accordance with our Privacy Policy and applicable law."},{t:"s",x:"4.6 Continuous Improvement"},{t:"p",x:"Fraud techniques continue to evolve. View2Earn regularly reviews and improves its fraud detection systems, monitoring procedures, and security practices to address emerging threats and maintain a fair and secure platform for all users. View2Earn reserves the right to introduce new fraud prevention technologies and monitoring measures as necessary, provided they are implemented in accordance with applicable laws and our Privacy Policy."},{t:"h",x:"5. Investigations"},{t:"p",x:"View2Earn takes all reports and indicators of suspected fraud seriously. When potential fraudulent, deceptive, abusive, or unauthorized activity is identified, we may conduct an investigation to determine whether this Anti-Fraud Policy, our Terms of Service, or other applicable platform policies have been violated. All investigations are conducted in good faith, fairly, consistently, and in accordance with applicable laws and our Privacy Policy."},{t:"s",x:"5.1 Initiation of an Investigation"},{t:"p",x:"An investigation may be initiated for reasons including, but not limited to, automated fraud detection alerts, reports submitted by users/advertisers/survey providers/business partners, suspicious account activity, unusual reward or referral patterns, verification failures, or suspected violations of this Policy or other platform rules. The initiation of an investigation does not necessarily mean that a violation has occurred."},{t:"s",x:"5.2 Information Reviewed"},{t:"p",x:"As part of an investigation, View2Earn may review information reasonably necessary to determine the facts, including account information, activity history, reward and redemption records, referral activity, survey and task completion records, device and technical information, login history, communications with our support team, and other relevant records relating to the suspected activity. Only information reasonably necessary for the investigation will be reviewed."},{t:"s",x:"5.3 User Cooperation"},{t:"p",x:"Users are expected to cooperate with legitimate investigations conducted by View2Earn. During an investigation, we may request additional information or documentation to verify account ownership, eligibility, or compliance with this Policy. Failure to respond within a reasonable period or the submission of false or misleading information may affect the outcome of the investigation."},{t:"s",x:"5.4 Temporary Measures"},{t:"p",x:"To protect the Service while an investigation is ongoing, View2Earn may temporarily suspend reward processing, delay reward redemption, restrict access to certain platform features, require additional identity or account verification, or place an account under temporary review. These measures are precautionary and do not, by themselves, indicate that a policy violation has been confirmed."},{t:"s",x:"5.5 Investigation Outcomes"},{t:"p",x:"After completing an investigation, View2Earn may determine that no violation occurred and remove any temporary restrictions; that additional information is required before a final decision can be made; or that a policy violation occurred, resulting in appropriate enforcement action under this Anti-Fraud Policy or our Terms of Service."},{t:"s",x:"5.6 Confidentiality"},{t:"p",x:"To protect the effectiveness of our fraud prevention efforts, View2Earn may limit the information disclosed about investigations, detection methods, evidence, or internal decision-making processes. We are not required to disclose confidential security procedures, fraud detection technologies, or investigative techniques that could compromise the security or integrity of the Service."},{t:"s",x:"5.7 Recordkeeping"},{t:"p",x:"View2Earn may retain records relating to investigations for an appropriate period where necessary to maintain platform security, prevent repeated fraudulent activity, resolve disputes, comply with legal or regulatory obligations, or enforce our legal rights and platform policies. Such records will be handled in accordance with our Privacy Policy and applicable data protection laws."},{t:"h",x:"6. Enforcement Actions"},{t:"p",x:"View2Earn reserves the right to take appropriate enforcement action whenever we reasonably determine that a user has violated this Anti-Fraud Policy, our Terms of Service, or any other applicable platform policy. The enforcement action taken will depend on the nature, severity, frequency, and impact of the violation, as well as any other relevant circumstances."},{t:"s",x:"6.1 Types of Enforcement Actions"},{t:"p",x:"Depending on the circumstances, View2Earn may issue a warning or educational notice, require additional account or identity verification, temporarily restrict access to certain features, delay or suspend reward processing or redemption, remove/adjust/cancel Reward Points obtained in violation of this Policy, cancel rewards earned through fraudulent or abusive activity, suspend an account for a specified period, permanently terminate an account, restrict participation in specific campaigns/surveys/promotional activities, or take any other reasonable action necessary to protect the Service."},{t:"s",x:"6.2 Recovery of Improper Benefits"},{t:"p",x:"If View2Earn determines that Reward Points, rewards, bonuses, referral benefits, or other advantages were obtained through fraud, deception, abuse, or policy violations, we may reverse the affected transactions, remove improperly earned Reward Points, cancel pending or future rewards related to the violation, or recover benefits obtained through fraudulent activity where permitted by applicable law."},{t:"s",x:"6.3 Repeat Violations"},{t:"p",x:"Users who repeatedly violate this Anti-Fraud Policy, even where individual violations are relatively minor, may be subject to increasingly severe enforcement actions, including permanent account termination. Repeated violations demonstrate a pattern of non-compliance that may threaten the integrity of the Service."},{t:"s",x:"6.4 Serious Violations"},{t:"p",x:"Certain violations may result in immediate enforcement action without prior warning, including but not limited to organized fraud schemes, identity theft or impersonation, large-scale reward manipulation, use of malicious software or attacks against the Service, deliberate attempts to compromise platform security, or fraud involving advertisers, survey providers, or business partners."},{t:"s",x:"6.5 No Right to Fraudulent Rewards"},{t:"p",x:"Users have no ownership or legal entitlement to Reward Points, bonuses, rewards, or promotional benefits obtained through fraudulent, deceptive, or unauthorized activities. View2Earn may cancel, reverse, or withhold such benefits at any time upon discovering a violation."},{t:"s",x:"6.6 Cooperation with Authorities"},{t:"p",x:"Where permitted or required by applicable law, View2Earn may cooperate with law enforcement agencies, regulatory authorities, courts, advertisers, survey providers, payment providers, blockchain ecosystem operators, and other authorized parties in connection with investigations involving suspected fraud, criminal activity, or legal violations. Any information shared will be limited to what is reasonably necessary and handled in accordance with applicable law and our Privacy Policy."},{t:"s",x:"6.7 Reservation of Rights"},{t:"p",x:"The enforcement actions described in this Policy are not exhaustive. View2Earn reserves all rights and remedies available under applicable law, our Terms of Service, and other platform policies to protect the Service, our users, advertisers, survey providers, business partners, and the broader View2Earn ecosystem."},{t:"h",x:"7. Appeals and Reviews"},{t:"p",x:"View2Earn is committed to enforcing this Anti-Fraud Policy fairly, consistently, and responsibly. If you believe that an enforcement action has been taken in error, you may request a review of the decision in accordance with this section. Submitting an appeal does not guarantee that the original decision will be changed or reversed."},{t:"s",x:"7.1 Right to Request a Review"},{t:"p",x:"Users may request a review of certain enforcement actions, including account suspensions, permanent account terminations, reward cancellations or forfeitures, Reward Point adjustments, participation restrictions, and other enforcement actions that View2Earn determines are eligible for review. Certain decisions, particularly those involving serious fraud, legal obligations, platform security, or criminal activity, may not be eligible for appeal."},{t:"s",x:"7.2 How to Submit an Appeal"},{t:"p",x:"Appeals should be submitted through the official support channels provided by View2Earn. When submitting an appeal, users should provide their account information, a clear description of the decision being challenged, any relevant evidence or supporting documentation, and any additional information that may assist in the review. Providing false, misleading, or fabricated information during an appeal may result in additional enforcement actions."},{t:"s",x:"7.3 Review Process"},{t:"p",x:"Each eligible appeal will be reviewed by authorized members of the View2Earn team. During the review process, we may consider the information provided by the user, account history, investigation records, technical and security data, evidence collected during the original investigation, and any newly submitted evidence. Additional information may be requested if necessary before a final decision is made."},{t:"s",x:"7.4 Decision on Appeal"},{t:"p",x:"After completing the review, View2Earn may uphold the original enforcement action, modify the enforcement action, reverse the enforcement action, restore eligible Reward Points or rewards where appropriate, or take any other action considered reasonable under the circumstances. The decision reached after an appeal will generally be considered final, except where additional evidence or legal obligations require further review."},{t:"s",x:"7.5 Timeframe"},{t:"p",x:"View2Earn will make reasonable efforts to review appeals within a reasonable period. The time required may vary depending on the complexity of the case, the availability of relevant information, ongoing investigations, and legal or regulatory requirements."},{t:"s",x:"7.6 Abuse of the Appeals Process"},{t:"p",x:"Users must not misuse the appeals process by submitting repeated appeals without new information, providing false or misleading evidence, harassing or threatening View2Earn personnel, or attempting to interfere with or influence the review process. Abuse of the appeals process may result in additional restrictions or enforcement actions."},{t:"s",x:"7.7 Fairness and Consistency"},{t:"p",x:"View2Earn strives to review appeals objectively, fairly, and consistently while protecting the integrity of the Service, our users, advertisers, survey providers, business partners, and the broader View2Earn ecosystem. Nothing in this section limits View2Earn's right to take immediate action where necessary to protect platform security, comply with legal obligations, or prevent fraud."},{t:"h",x:"8. Reporting Fraud"},{t:"p",x:"View2Earn encourages users, advertisers, survey providers, business partners, and members of the public to report suspected fraudulent, deceptive, abusive, or unauthorized activities that may affect the security, fairness, or integrity of the Service. Timely reporting helps us investigate potential violations, protect legitimate users, and maintain a trusted platform."},{t:"s",x:"8.1 What Should Be Reported"},{t:"p",x:"Reports may include, but are not limited to, multiple-account abuse, identity impersonation or account theft, fake referrals or referral manipulation, fraudulent reward claims, submission of false or manipulated evidence, survey or advertising fraud, use of bots/scripts/automation tools or other unauthorized technologies, attempts to exploit platform vulnerabilities, suspicious account activity, and any other conduct that may violate this Anti-Fraud Policy, our Terms of Service, or applicable laws."},{t:"s",x:"8.2 How to Report Fraud"},{t:"p",x:"Fraud reports should be submitted through View2Earn's official communication channels. When possible, reports should include a clear description of the suspected activity, the username/account identifier or other identifying information of the account involved (if known), the date and time of the incident (where available), relevant screenshots/documents or other supporting evidence, and any additional information that may assist our investigation."},{t:"s",x:"8.3 Confidentiality"},{t:"p",x:"View2Earn will make reasonable efforts to handle fraud reports confidentially. To protect the integrity of investigations and the privacy of all parties involved, we may limit the information shared about the progress, findings, or outcome of any investigation."},{t:"s",x:"8.4 Good Faith Reporting"},{t:"p",x:"Reports should be made honestly and in good faith. Knowingly submitting false, misleading, malicious, or fabricated reports, or attempting to misuse the reporting process to harass, intimidate, or damage another person or organization, may itself constitute a violation of this Policy and may result in appropriate enforcement action."},{t:"s",x:"8.5 Investigation of Reports"},{t:"p",x:"All credible reports will be assessed and, where appropriate, investigated by authorized members of the View2Earn team. The submission of a report does not guarantee that enforcement action will be taken. Decisions will be based on the available evidence, the results of any investigation, and the requirements of this Policy and applicable law."},{t:"s",x:"8.6 Protection Against Retaliation"},{t:"p",x:"View2Earn does not tolerate retaliation against any individual who, in good faith, reports suspected fraud or cooperates with a legitimate investigation. However, this protection does not apply to individuals who knowingly submit false reports or participate in fraudulent or abusive activities."},{t:"s",x:"8.7 Emergency Security Issues"},{t:"p",x:"If you believe that a security vulnerability or active fraud presents an immediate risk to the Service, users, advertisers, or business partners, please notify View2Earn as soon as possible through our official security contact: security@view2earn.org. We appreciate responsible and timely reporting and will investigate credible security concerns as quickly as reasonably possible."},{t:"h",x:"9. Cooperation with Third Parties"},{t:"p",x:"View2Earn recognizes that preventing and investigating fraud may require cooperation with trusted third parties. Where appropriate and permitted by applicable law, we may work with service providers, advertisers, survey providers, business partners, blockchain ecosystem operators, payment providers, regulatory authorities, and law enforcement agencies to protect the integrity, security, and fairness of the Service. Any cooperation will be carried out responsibly and in accordance with our Privacy Policy, Terms of Service, applicable laws, and contractual obligations."},{t:"s",x:"9.1 Trusted Service Providers"},{t:"p",x:"View2Earn may cooperate with trusted service providers that assist us in fraud detection and prevention, identity and account verification, platform security, cloud infrastructure and hosting, analytics and system monitoring, reward fulfillment, customer support, and technical investigations. These providers may receive only the information reasonably necessary to perform their services and are expected to maintain appropriate confidentiality and security standards."},{t:"s",x:"9.2 Advertisers and Survey Providers"},{t:"p",x:"To protect the integrity of advertising campaigns, surveys, and promotional activities, View2Earn may cooperate with advertisers, survey providers, and reward partners to verify task completion and eligibility, detect invalid traffic or fraudulent participation, investigate suspicious reward claims, prevent duplicate participation, and protect campaign integrity. Information shared for these purposes will be limited to what is reasonably necessary and consistent with applicable law."},{t:"s",x:"9.3 Blockchain Ecosystem Operators"},{t:"p",x:"Where fraud or abuse involves supported blockchain ecosystems, View2Earn may cooperate with the relevant blockchain ecosystem operators or authorized service providers, including Pi Network, Sidra Chain, or other supported ecosystems. Such cooperation may include verifying compliance with ecosystem rules, investigating suspected abuse, or protecting the integrity of blockchain-related activities. View2Earn respects the independence of each blockchain ecosystem and does not control their governance, policies, or enforcement decisions."},{t:"s",x:"9.4 Regulatory and Law Enforcement Authorities"},{t:"p",x:"Where required or permitted by applicable law, View2Earn may cooperate with courts, regulatory authorities, government agencies, or law enforcement in connection with investigations involving suspected fraud, financial crime, cybercrime, or other unlawful activities. Such cooperation may include responding to lawful requests, preserving relevant records, or providing information required by applicable law."},{t:"s",x:"9.5 Protection of Privacy"},{t:"p",x:"View2Earn is committed to protecting user privacy during all forms of cooperation with third parties. We will make reasonable efforts to ensure that only the minimum information reasonably necessary is shared, information is disclosed only for legitimate purposes, appropriate safeguards are applied to protect personal information, and any disclosure complies with applicable law and our Privacy Policy."},{t:"s",x:"9.6 Reservation of Rights"},{t:"p",x:"Nothing in this Policy requires View2Earn to disclose confidential security procedures, fraud detection methods, proprietary technologies, internal investigations, or information that could compromise the safety, security, or integrity of the Service. View2Earn reserves the right to determine the appropriate scope of cooperation in each case, subject to applicable law and our contractual obligations."},{t:"h",x:"10. User Responsibilities"},{t:"p",x:"All users of View2Earn are responsible for using the Service honestly, responsibly, and in compliance with this Anti-Fraud Policy, our Terms of Service, Privacy Policy, and all other applicable platform policies. Users are expected to contribute to a safe, fair, and trustworthy environment for the benefit of the entire View2Earn community."},{t:"s",x:"10.1 Accurate Information"},{t:"p",x:"Users must provide accurate, complete, and truthful information when creating and maintaining their accounts. Users are responsible for keeping their account information up to date and must not provide false, misleading, or fraudulent information."},{t:"s",x:"10.2 Account Security"},{t:"p",x:"Users are responsible for maintaining the confidentiality and security of their account credentials. Users should use strong and unique passwords, protect their login credentials from unauthorized access, enable additional security features where available, and notify View2Earn immediately if they suspect unauthorized access to their account. Users are responsible for activities performed through their accounts unless otherwise required by applicable law."},{t:"s",x:"10.3 Compliance with Platform Policies"},{t:"p",x:"Users must comply with this Anti-Fraud Policy, the Terms of Service, the Privacy Policy, the Cookie Policy, and any additional policies, guidelines, or rules published by View2Earn. Failure to comply with these policies may result in enforcement action."},{t:"s",x:"10.4 Honest Participation"},{t:"p",x:"Users must participate honestly in all platform activities, including completing tasks, participating in surveys, referring new users, redeeming rewards, and engaging with promotional campaigns. Any attempt to manipulate, deceive, or abuse these activities is strictly prohibited."},{t:"s",x:"10.5 Reporting Suspicious Activity"},{t:"p",x:"Users are encouraged to promptly report suspected fraud, abuse, security vulnerabilities, or policy violations through View2Earn's official communication channels. Reports should be made honestly, responsibly, and in good faith."},{t:"s",x:"10.6 Cooperation with Investigations"},{t:"p",x:"Where reasonably requested, users should cooperate with legitimate investigations conducted by View2Earn. This may include providing additional information or documentation necessary to verify account ownership, reward eligibility, or compliance with platform policies. Failure to cooperate may affect the outcome of an investigation."},{t:"s",x:"10.7 Responsible Use of the Service"},{t:"p",x:"Users must not use the Service in any manner that could harm other users, damage the reputation of View2Earn, disrupt platform operations, interfere with advertisers/survey providers/business partners, or compromise the security, stability, or integrity of the Service."},{t:"s",x:"10.8 Shared Responsibility"},{t:"p",x:"Maintaining a secure and trustworthy platform is a shared responsibility between View2Earn and its users. View2Earn is committed to providing effective fraud prevention measures, while users are expected to act honestly, responsibly, and in accordance with this Policy."},{t:"h",x:"11. Changes to This Anti-Fraud Policy"},{t:"p",x:"View2Earn may update this Anti-Fraud Policy from time to time to reflect changes in our Services, fraud prevention practices, technologies, legal obligations, industry standards, or business operations. We are committed to maintaining transparency and will make reasonable efforts to keep users informed of significant changes to this Policy."},{t:"s",x:"11.1 Reasons for Updates"},{t:"p",x:"View2Earn may revise this Anti-Fraud Policy for reasons including, but not limited to, introducing new features/products/services, responding to emerging fraud techniques or security threats, improving fraud detection/prevention/investigation procedures, complying with new laws/regulations/court decisions/regulatory guidance, reflecting changes in our business operations/partnerships/supported technologies, and clarifying or improving existing provisions for greater transparency and consistency."},{t:"s",x:"11.2 Notification of Changes"},{t:"p",x:"When material changes are made to this Anti-Fraud Policy, View2Earn may notify users through one or more of the following methods: publishing the updated Policy on the View2Earn website or mobile application, displaying an in-app notification, sending an email to the registered email address associated with the user's account (where appropriate), or using any other communication method that View2Earn reasonably considers appropriate. Minor editorial, formatting, or administrative changes that do not materially affect users' rights or responsibilities may be made without individual notice."},{t:"s",x:"11.3 Effective Date"},{t:"p",x:'The most current version of this Anti-Fraud Policy will always display a "Last Updated" date at the beginning of the document. Unless otherwise required by applicable law, updates become effective upon publication. Where required by law or where changes materially affect users, View2Earn may provide advance notice before the updated Policy takes effect.'},{t:"s",x:"11.4 Continued Use of the Service"},{t:"p",x:"By continuing to access or use the Service after an updated Anti-Fraud Policy becomes effective, you acknowledge that you have been informed of the revised Policy and agree to comply with it. If you do not agree with the updated Policy, you should discontinue using the Service and may close your account in accordance with our Terms of Service."},{t:"s",x:"11.5 Reservation of Rights"},{t:"p",x:"Nothing in this section limits View2Earn's ability to take immediate action to protect the Service, its users, advertisers, survey providers, business partners, or the broader platform ecosystem where necessary to address fraud, security threats, legal obligations, or other urgent circumstances."},{t:"h",x:"12. Contact Information"},{t:"p",x:"View2Earn is committed to maintaining a secure, fair, and trustworthy platform. If you have questions about this Anti-Fraud Policy, wish to report suspected fraud, appeal an enforcement decision, or report a security concern, please contact us using the appropriate communication channel below."},{t:"l",x:["Fraud Reports: fraud@view2earn.org","Appeals and Enforcement Reviews: appeals@view2earn.org","Security Vulnerability Reports: security@view2earn.org","General Support: support@view2earn.org","Legal Team: legal@view2earn.org","Business Partnerships: partners@view2earn.org"]},{t:"p",x:"View2Earn will make reasonable efforts to acknowledge and respond to legitimate reports and inquiries within a reasonable timeframe. The time required to investigate or respond may vary depending on the complexity of the matter, the availability of supporting information, ongoing investigations, and legal or regulatory requirements."},{t:"p",x:"To protect users, business partners, and the integrity of our fraud prevention processes, View2Earn may limit the information disclosed about investigations, enforcement actions, or internal security procedures. Information provided to View2Earn will be handled in accordance with our Privacy Policy and applicable law."}]},rewards:{key:"rewards",title:"Rewards & Redemption Policy",badge:"REWARDS & REDEMPTION",lastUpdated:"August 2026",blocks:[{t:"h",x:"1. Introduction"},{t:"p",x:'Welcome to View2Earn. This Rewards & Redemption Policy ("Policy") explains how users earn, accumulate, verify, redeem, and receive rewards through the View2Earn platform ("Service").'},{t:"p",x:"View2Earn is committed to providing a transparent, fair, and secure rewards system that benefits users, advertisers, survey providers, business partners, and the broader platform ecosystem."},{t:"p",x:"This Policy forms part of the View2Earn Terms of Service and should be read together with our Privacy Policy, Cookie Policy, Anti-Fraud Policy, and any other applicable platform policies. By creating an account, participating in platform activities, earning Reward Points, or redeeming rewards, you agree to comply with this Policy."},{t:"p",x:"Reward Points are promotional loyalty points issued by View2Earn. They are not legal tender, electronic money, cryptocurrency, securities, stored-value products, or bank deposits, and they have no cash value except where View2Earn expressly offers an approved redemption option."},{t:"p",x:"View2Earn reserves the right to verify all reward activity, investigate suspicious behavior, delay or refuse redemptions where necessary, and take appropriate action to protect the integrity, security, and fairness of the rewards system."},{t:"p",x:"Participation in the rewards program does not guarantee eligibility for every campaign, task, survey, promotion, or reward. Eligibility may depend on factors such as account status, geographic location, verification requirements, advertiser or survey provider criteria, campaign rules, and compliance with all applicable platform policies."},{t:"p",x:"View2Earn is committed to ensuring that rewards are earned honestly, distributed fairly, and redeemed securely for the benefit of all legitimate users."},{t:"h",x:"2. Eligibility for Rewards"},{t:"p",x:"To maintain a fair, secure, and trustworthy rewards program, users must satisfy the eligibility requirements established by View2Earn before earning or redeeming Reward Points. Meeting these requirements does not guarantee eligibility for every campaign, task, survey, or promotional offer, as additional criteria may apply."},{t:"s",x:"2.1 Account Eligibility"},{t:"p",x:"To participate in the rewards program, users must maintain an active and valid View2Earn account, be at least 18 years of age or the minimum legal age required in their jurisdiction, provide accurate/complete/truthful account information, comply with the View2Earn Terms of Service, Privacy Policy, Cookie Policy, Anti-Fraud Policy, and this Rewards & Redemption Policy, and successfully complete any verification procedures required by View2Earn."},{t:"p",x:"Accounts that are suspended, restricted, terminated, or under investigation may not be eligible to earn or redeem rewards."},{t:"s",x:"2.2 Campaign Eligibility"},{t:"p",x:"Certain rewards, surveys, advertisements, promotions, or special campaigns may have additional eligibility requirements, including country or regional availability, language requirements, age restrictions, device compatibility, account verification status, advertiser or survey provider requirements, and campaign-specific participation rules. Users are responsible for reviewing and complying with all campaign requirements before participating."},{t:"s",x:"2.3 Good Standing"},{t:"p",x:"To remain eligible for rewards, users must maintain their accounts in good standing. Users may become ineligible if they violate platform policies, engage in fraudulent or abusive activities, submit false or misleading information, attempt to manipulate the rewards system, or fail to satisfy verification requirements. View2Earn reserves the right to suspend or revoke eligibility where there is reasonable evidence of policy violations or misuse of the Service."},{t:"s",x:"2.4 Verification Requirements"},{t:"p",x:"View2Earn may require users to complete identity, account, device, or activity verification before allowing them to earn or redeem rewards. Verification requirements may vary depending on the type of reward, reward value, geographic location, applicable legal or regulatory requirements, and fraud risk assessment. Failure to complete required verification may result in delayed, restricted, or denied participation in the rewards program."},{t:"s",x:"2.5 Independent Eligibility Decisions"},{t:"p",x:"Eligibility for rewards is determined solely by View2Earn and, where applicable, by advertisers, survey providers, or other authorized partners. Participation in one campaign or successful completion of previous activities does not guarantee eligibility for future opportunities. View2Earn reserves the right to determine, verify, or revoke eligibility at any time where necessary to protect the integrity, security, fairness, or lawful operation of the rewards program."},{t:"h",x:"3. Earning Reward Points"},{t:"p",x:"View2Earn rewards users for completing eligible activities that contribute to the growth, engagement, and integrity of the platform. Reward Points are earned only after the successful completion and verification of qualifying activities in accordance with this Policy and any applicable campaign rules. Reward Points are promotional loyalty points and do not represent money, cryptocurrency, securities, or any other financial instrument."},{t:"s",x:"3.1 Eligible Activities"},{t:"p",x:"Users may earn Reward Points by participating in eligible activities made available through the Service, including but not limited to completing surveys, watching advertisements or promotional content, following or engaging with approved social media campaigns, completing promotional tasks, inviting eligible users through the referral program, participating in quizzes/contests/special events, completing bonus missions or achievement programs, and participating in future activities introduced by View2Earn. The availability of activities may vary by country, device, language, account status, advertiser requirements, and other eligibility criteria."},{t:"s",x:"3.2 Completion Requirements"},{t:"p",x:"Reward Points are awarded only when all applicable requirements have been successfully completed. Depending on the activity, users may be required to complete every required step, follow all campaign instructions, meet advertiser or survey provider requirements, successfully pass validation or verification checks, and maintain compliance with all View2Earn policies. Incomplete, inaccurate, or invalid activity may not qualify for Reward Points."},{t:"s",x:"3.3 Verification Before Awarding Points"},{t:"p",x:"All eligible activities are subject to verification before Reward Points are credited. Verification may be performed by View2Earn, advertisers, survey providers, reward partners, automated verification systems, or manual review by authorized personnel. Reward Points will only be credited after successful verification has been completed."},{t:"s",x:"3.4 Pending Reward Points"},{t:"p",x:"Some Reward Points may initially appear as Pending while verification is in progress. Pending points are not yet available for redemption, may remain pending until advertiser or partner confirmation is received, may be adjusted/approved/rejected following verification, and do not guarantee final approval. The verification period may vary depending on the campaign or partner requirements."},{t:"s",x:"3.5 Promotional Bonuses"},{t:"p",x:"From time to time, View2Earn may offer promotional bonuses, limited-time campaigns, referral incentives, seasonal events, loyalty rewards, or other special earning opportunities. Each promotion may have its own eligibility requirements, participation rules, earning limits, validity period, and redemption conditions. Unless otherwise stated, promotional bonuses are governed by this Policy in addition to the specific terms of the relevant promotion."},{t:"s",x:"3.6 Situations Where Points May Not Be Awarded"},{t:"p",x:"Reward Points may be refused, delayed, adjusted, or cancelled where activity cannot be verified, campaign requirements are not fully completed, the advertiser or survey provider rejects the activity, duplicate participation is detected, fraudulent or abusive activity is identified, technical errors invalidate the activity, or platform policies or campaign rules have been violated. View2Earn's decision regarding the awarding of Reward Points will be based on the available evidence, verification results, and applicable campaign requirements."},{t:"s",x:"3.7 No Guarantee of Earnings"},{t:"p",x:"The availability of earning opportunities may change at any time. View2Earn does not guarantee a minimum number of available tasks or surveys, continuous availability of earning opportunities, approval of every completed activity, or a specific amount of Reward Points or rewards. Earning opportunities depend on factors including advertiser demand, campaign availability, geographic eligibility, verification results, user qualification, and platform operations."},{t:"s",x:"3.8 Platform Discretion"},{t:"p",x:"View2Earn reserves the right to introduce, modify, suspend, or discontinue earning opportunities, promotional campaigns, bonus programs, reward rates, or eligibility requirements at any time. Such changes may be made to improve the Service, prevent fraud, comply with legal obligations, respond to business needs, or protect the integrity of the rewards program."},{t:"h",x:"4. Reward Verification"},{t:"p",x:"To maintain a fair, secure, and reliable rewards program, all Reward Points and reward claims are subject to verification before they are approved or made available for redemption. Verification helps ensure that rewards are issued only for genuine, eligible, and successfully completed activities while protecting the interests of users, advertisers, survey providers, business partners, and the View2Earn platform."},{t:"s",x:"4.1 Verification Process"},{t:"p",x:"Before Reward Points are awarded, View2Earn may verify that the activity was completed successfully, all campaign requirements were satisfied, the user met the applicable eligibility criteria, no fraudulent/deceptive/abusive activity occurred, and the activity complies with this Policy and all other applicable platform policies. Verification requirements may vary depending on the activity, reward type, campaign, or partner."},{t:"s",x:"4.2 Verification Methods"},{t:"p",x:"View2Earn may use one or more verification methods, including automated validation systems, manual review by authorized personnel, advertiser confirmation, survey provider validation, referral verification, device and security checks, activity and behavioral analysis, and additional verification procedures where reasonably necessary. The verification method used may differ depending on the nature and risk level of the activity."},{t:"s",x:"4.3 Pending Verification"},{t:"p",x:"Reward Points may remain in a Pending status while verification is being completed. Pending Reward Points cannot be redeemed or transferred, may be approved/adjusted/delayed/rejected, do not guarantee final approval, and may remain pending until confirmation is received from the relevant advertiser, survey provider, or other authorized partner. Users should not assume that pending Reward Points have been permanently earned until they are officially approved."},{t:"s",x:"4.4 Additional Verification"},{t:"p",x:"Where necessary, View2Earn may request additional information or verification before approving rewards. This may include identity verification, account ownership confirmation, device verification, confirmation of task completion, and supporting documentation where appropriate. Failure to complete requested verification within a reasonable period may result in delayed or rejected rewards."},{t:"s",x:"4.5 Verification Timeframes"},{t:"p",x:"Verification times may vary depending on the type of activity, advertiser or survey provider processing times, campaign requirements, fraud prevention reviews, and technical or operational factors. While View2Earn aims to process verifications as efficiently as possible, we cannot guarantee that all rewards will be verified within a specific timeframe."},{t:"s",x:"4.6 Rejected Activities"},{t:"p",x:"Reward Points may be rejected if the activity fails verification, campaign requirements were not satisfied, duplicate participation is detected, fraudulent or suspicious activity is identified, the advertiser or survey provider declines the activity, or platform policies have been violated. Where appropriate, users may contact View2Earn Support if they believe a verification decision was made in error."},{t:"s",x:"4.7 Final Verification Decisions"},{t:"p",x:"View2Earn reserves the right to make the final determination regarding reward verification after considering all available evidence, verification results, partner feedback, and applicable platform policies. Verification decisions are made in good faith to protect the integrity, fairness, and sustainability of the rewards program and may be subject to review under our applicable appeals process where eligible."},{t:"h",x:"5. Reward Point Balances"},{t:"p",x:"View2Earn provides users with a Reward Point balance that reflects their participation in eligible activities and approved rewards. Users are responsible for reviewing their balances regularly and notifying View2Earn of any suspected discrepancies. Reward Point balances are maintained electronically within the Service and are subject to verification, adjustments, and applicable platform policies."},{t:"s",x:"5.1 Balance Categories"},{t:"p",x:"Your Reward Point balance may include one or more of the following categories: Available Points (successfully verified and eligible for redemption), Pending Points (awaiting verification or approval; not available for redemption and may be approved, adjusted, delayed, or rejected), and Adjusted Points (added or deducted as a result of corrections, fraud investigations, promotional updates, technical issues, or administrative actions). Where applicable, the Service may display these categories separately to provide greater transparency."},{t:"s",x:"5.2 Balance Updates"},{t:"p",x:"Reward Point balances may be updated when a qualifying activity has been successfully verified, a reward has been redeemed, a promotional bonus has been awarded, pending Reward Points are approved or rejected, administrative corrections are required, fraudulent or invalid activities are identified, or other adjustments are made in accordance with this Policy. Balance updates may not always occur immediately and may be subject to verification or processing delays."},{t:"s",x:"5.3 Viewing Your Balance"},{t:"p",x:"Users may view their current Reward Point balance through the View2Earn website, mobile application, or other official platform interfaces made available by View2Earn. The displayed balance should be used as the primary record of Reward Points associated with your account."},{t:"s",x:"5.4 Balance Accuracy"},{t:"p",x:"View2Earn makes reasonable efforts to maintain accurate Reward Point balances. However, temporary discrepancies may occur due to verification processes, technical maintenance, synchronization delays, advertiser or survey provider confirmations, or system errors requiring correction. Where an error is identified, View2Earn may correct the balance without prior notice where reasonably necessary."},{t:"s",x:"5.5 Reporting Balance Discrepancies"},{t:"p",x:"If you believe your Reward Point balance is incorrect, you should contact View2Earn Support as soon as reasonably possible. When reporting a discrepancy, please provide your account information, a description of the issue, the relevant activity or transaction, the approximate date and time, and any supporting evidence that may assist our review. View2Earn will investigate legitimate reports and make appropriate corrections where necessary."},{t:"s",x:"5.6 No Ownership Interest"},{t:"p",x:"Reward Points are promotional loyalty points issued by View2Earn. Unless expressly stated otherwise, Reward Points are not cash, are not cryptocurrency, are not bank deposits, are not investment products, do not earn interest, and have no monetary value except through authorized redemption options offered by View2Earn. Users do not acquire any ownership, property, or transferable legal rights in Reward Points beyond those expressly granted under this Policy."},{t:"s",x:"5.7 Final Balance Determination"},{t:"p",x:"The official Reward Point balance maintained by View2Earn will be considered the authoritative record for all reward-related purposes. View2Earn reserves the right to correct errors, investigate discrepancies, adjust balances, and reverse unauthorized or fraudulent Reward Points whenever reasonably necessary to protect the integrity of the rewards program."},{t:"h",x:"6. Redemption Requirements"},{t:"p",x:"Users may redeem eligible Reward Points for available rewards through the View2Earn platform, subject to this Policy, applicable campaign rules, and any additional requirements established by View2Earn. Redemptions are intended to provide fair and secure access to rewards while protecting the integrity of the rewards program and the interests of users, advertisers, survey providers, and business partners."},{t:"s",x:"6.1 Eligibility for Redemption"},{t:"p",x:"To redeem Reward Points, users must maintain an active View2Earn account in good standing, have sufficient Available Reward Points to complete the redemption, successfully complete any required account or identity verification, comply with all applicable View2Earn policies, and meet any additional requirements applicable to the selected reward. Users whose accounts are suspended, restricted, under investigation, or otherwise ineligible may be prevented from redeeming rewards."},{t:"s",x:"6.2 Available Rewards"},{t:"p",x:"View2Earn may offer different redemption options depending on the user's location, account status, supported blockchain ecosystem, promotional campaigns, and business partnerships. Available rewards may include digital rewards, gift cards, platform credits, approved blockchain-based rewards, promotional merchandise, and other rewards introduced by View2Earn from time to time. The availability, value, and redemption requirements of rewards may change without prior notice."},{t:"s",x:"6.3 Minimum Redemption Requirements"},{t:"p",x:"Certain rewards may require users to meet minimum redemption thresholds before a redemption request can be submitted. Minimum requirements may vary depending on reward type, reward value, geographic location, payment or fulfillment method, promotional campaign rules, and applicable legal or regulatory requirements. The applicable redemption requirements will be displayed within the Service whenever reasonably possible."},{t:"s",x:"6.4 Redemption Verification"},{t:"p",x:"Before processing a redemption request, View2Earn may verify the user's identity, account ownership, Reward Point balance, compliance with platform policies, eligibility for the selected reward, and the absence of fraudulent or suspicious activity. Additional verification may be requested where reasonably necessary."},{t:"s",x:"6.5 Redemption Requests"},{t:"p",x:"Submitting a redemption request does not guarantee immediate approval or delivery. All redemption requests remain subject to verification, fraud prevention checks, reward availability, partner confirmation where applicable, and operational and technical requirements. View2Earn reserves the right to approve, delay, reject, or cancel redemption requests where justified under this Policy."},{t:"s",x:"6.6 Redemption Refusal"},{t:"p",x:"View2Earn may refuse or cancel a redemption request where insufficient Available Reward Points exist, verification requirements have not been completed, fraud or suspicious activity is detected, platform policies have been violated, the requested reward is unavailable, technical or operational issues prevent fulfillment, or redemption would violate applicable law or contractual obligations. Where appropriate, users may be notified of the reason for the refusal, except where disclosure could compromise fraud prevention, security measures, or legal obligations."},{t:"s",x:"6.7 Final Redemption Decision"},{t:"p",x:"View2Earn reserves the right to make the final determination regarding all redemption requests. All redemption decisions will be made in good faith based on this Policy, applicable campaign rules, verification results, fraud prevention measures, operational requirements, and legal obligations. Nothing in this Policy guarantees that every redemption request will be approved or fulfilled."},{t:"h",x:"7. Reward Processing"},{t:"p",x:"Once a redemption request has been submitted, View2Earn will process the request in accordance with this Policy, applicable campaign rules, verification requirements, and operational procedures. Our goal is to deliver rewards accurately, securely, and as efficiently as reasonably possible while maintaining the integrity of the rewards program."},{t:"s",x:"7.1 Processing Stages"},{t:"p",x:"A redemption request may pass through several stages before completion, including submission of the redemption request, verification of account eligibility, validation of Available Reward Points, fraud prevention and security checks, partner or advertiser confirmation (where applicable), reward approval, and reward fulfillment or delivery. The processing stages may vary depending on the type of reward and the fulfillment method."},{t:"s",x:"7.2 Processing Time"},{t:"p",x:"Processing times may vary based on the type of reward requested, verification requirements, advertiser or partner processing times, blockchain network conditions (where applicable), payment or fulfillment provider processing, and technical maintenance or operational requirements. View2Earn will make reasonable efforts to process rewards promptly but does not guarantee delivery within a specific timeframe unless expressly stated."},{t:"s",x:"7.3 Reward Delivery"},{t:"p",x:"Approved rewards may be delivered through one or more of the following methods, depending on the selected reward: digital delivery through the View2Earn platform, email delivery, blockchain wallet transfer (where supported), gift card or voucher issuance, third-party fulfillment providers, or other delivery methods introduced by View2Earn. Users are responsible for ensuring that the information provided for reward delivery is accurate and complete."},{t:"s",x:"7.4 Delays"},{t:"p",x:"Reward processing or delivery may be delayed due to additional verification requirements, fraud prevention reviews, technical issues, service interruptions, partner or advertiser processing delays, blockchain network congestion, high redemption volumes, or events beyond View2Earn's reasonable control. View2Earn is not responsible for delays caused by third-party providers or circumstances outside our reasonable control."},{t:"s",x:"7.5 Failed or Unsuccessful Delivery"},{t:"p",x:"If a reward cannot be delivered because of incorrect user information, an inaccessible wallet or email address, technical issues on the user's side, or other circumstances attributable to the user, View2Earn may request updated information, attempt delivery again where reasonably practicable, or cancel the redemption if delivery remains impossible. Additional verification may be required before another delivery attempt is made."},{t:"s",x:"7.6 Third-Party Fulfillment"},{t:"p",x:"Some rewards may be provided or fulfilled by third-party partners. Where third-party fulfillment applies, delivery times may vary, additional partner terms may apply, availability may be subject to partner limitations, and View2Earn is not responsible for delays or interruptions caused solely by third-party providers. However, View2Earn will make reasonable efforts to assist users in resolving legitimate fulfillment issues where appropriate."},{t:"s",x:"7.7 Completion of Processing"},{t:"p",x:"A redemption request will be considered completed when the reward has been successfully delivered or otherwise made available to the user through the approved delivery method. View2Earn's records regarding reward processing, approval, and delivery will be considered the official record unless demonstrated otherwise by reliable evidence."},{t:"s",x:"7.8 Reservation of Rights"},{t:"p",x:"View2Earn reserves the right to delay, suspend, modify, or cancel reward processing where reasonably necessary to protect platform security, prevent fraud or abuse, comply with legal or regulatory obligations, resolve technical issues, correct administrative errors, or protect the integrity and sustainability of the rewards program."},{t:"h",x:"8. Reward Limits and Restrictions"},{t:"p",x:"To maintain a fair, secure, and sustainable rewards program, View2Earn may establish limits and restrictions on the earning, accumulation, redemption, and use of Reward Points and rewards. These limits help protect users, advertisers, survey providers, business partners, and the overall integrity of the View2Earn platform."},{t:"s",x:"8.1 Earning Limits"},{t:"p",x:"View2Earn may impose limits on the number of Reward Points that a user may earn within a specified period. Limits may include daily earning limits, weekly earning limits, monthly earning limits, campaign-specific earning limits, and lifetime earning limits for certain promotions or events. The applicable limits may vary depending on the activity, reward program, user status, or promotional campaign."},{t:"s",x:"8.2 Redemption Limits"},{t:"p",x:"To promote fairness and operational efficiency, View2Earn may establish redemption limits, including minimum redemption thresholds, maximum redemption amounts per transaction, daily/weekly/monthly redemption limits, limits based on account verification status, and limits applicable to specific reward types or geographic regions. These limits may change from time to time and will be communicated through the Service where reasonably practicable."},{t:"s",x:"8.3 Campaign Restrictions"},{t:"p",x:"Certain campaigns, surveys, promotions, contests, or bonus programs may include additional restrictions, such as limited participation periods, limited reward quantities, geographic eligibility, device or platform compatibility, age or demographic requirements, one-time participation limits, and advertiser or partner-specific eligibility requirements. Users are responsible for reviewing and complying with the rules applicable to each campaign before participating."},{t:"s",x:"8.4 Geographic Restrictions"},{t:"p",x:"Some rewards or earning opportunities may not be available in all countries or regions due to legal or regulatory requirements, advertiser or partner availability, payment or fulfillment limitations, or technical or operational considerations. View2Earn reserves the right to restrict or modify reward availability based on a user's location."},{t:"s",x:"8.5 Account-Based Restrictions"},{t:"p",x:"Reward eligibility and redemption may be limited for accounts that are newly created, pending verification, under investigation, temporarily restricted or suspended, associated with suspicious or fraudulent activity, or otherwise determined to present an elevated risk to the platform. Such restrictions are intended to protect the integrity and security of the rewards program."},{t:"s",x:"8.6 Abuse Prevention"},{t:"p",x:"Users must not attempt to bypass or manipulate any earning or redemption limits by creating multiple accounts, coordinating fraudulent activities with others, using automated tools or unauthorized software, exploiting technical vulnerabilities, or circumventing platform controls. Any attempt to evade platform limits may result in enforcement action under the Anti-Fraud Policy and Terms of Service."},{t:"s",x:"8.7 Modification of Limits"},{t:"p",x:"View2Earn reserves the right to introduce, modify, suspend, or remove reward limits and restrictions at any time to improve the rewards program, prevent fraud and abuse, respond to operational requirements, comply with legal or regulatory obligations, or support new features/products/promotional campaigns. Where appropriate, significant changes will be communicated through the Service or other official communication channels."},{t:"s",x:"8.8 Final Determination"},{t:"p",x:"View2Earn reserves the right to determine the applicability and enforcement of reward limits and restrictions in accordance with this Policy, our Terms of Service, and applicable law. Our decisions will be made in good faith to maintain a fair, secure, and sustainable rewards ecosystem for all users."},{t:"h",x:"9. Expiration of Reward Points"},{t:"p",x:"View2Earn may establish expiration periods for Reward Points to maintain an active, fair, and sustainable rewards program. Unless otherwise stated, Reward Points remain valid only for the period specified by View2Earn and may expire if they are not redeemed within the applicable timeframe. The applicable expiration period may vary depending on the type of Reward Points, promotional campaign, reward program, or other operational requirements."},{t:"s",x:"9.1 Expiration Period"},{t:"p",x:"Where an expiration period applies, View2Earn will make reasonable efforts to inform users through the Service or other official communication channels. The applicable expiration period may differ for standard Reward Points, promotional or bonus Reward Points, referral rewards, campaign-specific rewards, and limited-time promotional events."},{t:"s",x:"9.2 Account Inactivity"},{t:"p",x:"Reward Points may expire if an account remains inactive for an extended period. Account inactivity may include no login activity, no eligible earning activity, no redemption activity, or no meaningful participation in the Service. The applicable inactivity period may be determined by View2Earn and may change from time to time."},{t:"s",x:"9.3 Promotional Reward Points"},{t:"p",x:"Reward Points awarded as part of promotional campaigns, contests, seasonal events, referral programs, or bonus offers may have shorter validity periods. Any special expiration date or redemption deadline will be communicated as part of the applicable promotion. Unless otherwise stated, promotional Reward Points are subject to this Policy in addition to the terms of the specific promotion."},{t:"s",x:"9.4 Closed, Suspended, or Terminated Accounts"},{t:"p",x:"If an account is voluntarily closed, permanently suspended, or terminated in accordance with the Terms of Service or Anti-Fraud Policy, unredeemed Reward Points may be forfeited, pending Reward Points may be cancelled, and outstanding redemption requests may be reviewed, delayed, or cancelled where appropriate. Users are encouraged to redeem eligible Reward Points before voluntarily closing their accounts, subject to applicable redemption requirements."},{t:"s",x:"9.5 No Cash Compensation"},{t:"p",x:"Expired or forfeited Reward Points cannot be exchanged for cash, cryptocurrency, credit, refunds, or other compensation unless expressly required by applicable law. View2Earn is under no obligation to restore expired Reward Points except where the expiration resulted from a verified administrative or technical error."},{t:"s",x:"9.6 Administrative Corrections"},{t:"p",x:"If Reward Points expire due to a verified system error or administrative mistake, View2Earn may, at its sole discretion, restore the affected Reward Points after completing an appropriate review. Users should promptly report suspected errors through our official support channels."},{t:"s",x:"9.7 Changes to Expiration Rules"},{t:"p",x:"View2Earn reserves the right to introduce, modify, suspend, or remove Reward Point expiration rules where reasonably necessary to improve the rewards program, support new features or promotional campaigns, prevent fraud or abuse, comply with legal or regulatory obligations, or maintain the long-term sustainability of the rewards ecosystem. Where required by applicable law, or where changes materially affect users, View2Earn will provide reasonable notice before the updated rules take effect."},{t:"s",x:"9.8 Final Determination"},{t:"p",x:"View2Earn reserves the right to determine the validity, expiration, forfeiture, or restoration of Reward Points in accordance with this Policy, our Terms of Service, and applicable law. All decisions relating to Reward Point expiration will be made in good faith and with the objective of maintaining a fair, secure, and sustainable rewards program for all users."},{t:"h",x:"10. Fraud Prevention"},{t:"p",x:"View2Earn is committed to maintaining a fair, secure, and trustworthy rewards program. To protect legitimate users, advertisers, survey providers, business partners, and the integrity of the Service, all reward-related activities are subject to fraud prevention measures. View2Earn reserves the right to monitor, verify, investigate, and take appropriate action against any activity that may compromise the fairness or security of the rewards program."},{t:"s",x:"10.1 Fraud Prevention Measures"},{t:"p",x:"View2Earn may use automated systems, manual reviews, and other reasonable security measures to detect and prevent fraudulent or abusive activities. These measures may include account verification, identity verification, device and network analysis, activity monitoring, reward verification, referral validation, behavioral analysis, and security and risk assessments. These measures are designed to protect the integrity of the rewards program while minimizing the impact on legitimate users."},{t:"s",x:"10.2 Suspicious Activity"},{t:"p",x:"Reward Points, redemption requests, or account activities may be reviewed if View2Earn reasonably believes they involve multiple-account abuse, automated or bot activity, fraudulent referrals, false or manipulated task submissions, duplicate reward claims, survey or advertising fraud, unauthorized account access, attempts to exploit system vulnerabilities, or any other activity that may violate this Policy or the Anti-Fraud Policy. The identification of suspicious activity does not automatically mean that a violation has occurred; additional verification or investigation may be required."},{t:"s",x:"10.3 Temporary Holds"},{t:"p",x:"To protect the rewards program, View2Earn may temporarily place Reward Points or redemption requests on hold while verification or an investigation is being completed. During this period, users may experience delayed Reward Point approval, delayed reward processing, temporary redemption restrictions, requests for additional verification, or temporary account limitations. These measures are precautionary and do not necessarily indicate wrongdoing."},{t:"s",x:"10.4 Fraudulent Rewards"},{t:"p",x:"If View2Earn determines that Reward Points or rewards were obtained through fraudulent, deceptive, abusive, or unauthorized activities, we may reject or cancel pending Reward Points, remove previously awarded Reward Points, reverse completed reward transactions where reasonably possible, cancel redemption requests, recover improperly obtained rewards where permitted by law, suspend or permanently terminate the user's account, and take additional action under our Anti-Fraud Policy and Terms of Service."},{t:"s",x:"10.5 Cooperation with Partners"},{t:"p",x:"View2Earn may cooperate with advertisers, survey providers, reward partners, payment providers, and other trusted service providers to verify activities, investigate suspicious conduct, and protect the integrity of the rewards program. Information shared for these purposes will be limited to what is reasonably necessary and handled in accordance with our Privacy Policy and applicable law."},{t:"s",x:"10.6 User Responsibilities"},{t:"p",x:"Users are expected to participate honestly in all earning opportunities, follow campaign and platform rules, protect their account credentials, report suspected fraud or security issues, and cooperate with legitimate investigations conducted by View2Earn. Failure to comply with these responsibilities may result in enforcement action."},{t:"s",x:"10.7 Final Determination"},{t:"p",x:"View2Earn reserves the right to make the final determination regarding suspected reward fraud, verification outcomes, reward eligibility, and enforcement actions. All decisions will be made in good faith based on available evidence, verification results, applicable platform policies, contractual obligations, and legal requirements. Nothing in this section limits View2Earn's rights under its Anti-Fraud Policy, Terms of Service, or applicable law."},{t:"h",x:"11. Errors and Adjustments"},{t:"p",x:"View2Earn is committed to maintaining an accurate, fair, and reliable rewards program. Despite our best efforts, technical, administrative, operational, or third-party errors may occasionally occur. This section explains how such errors are handled and the circumstances under which Reward Points, rewards, or account balances may be corrected."},{t:"s",x:"11.1 Correction of Errors"},{t:"p",x:"View2Earn reserves the right to identify, investigate, and correct any error affecting Reward Points, reward balances, redemptions, promotions, or other aspects of the rewards program. Corrections may be made whether the error benefits or disadvantages a user."},{t:"s",x:"11.2 Types of Errors"},{t:"p",x:"Errors may include, but are not limited to, incorrect Reward Point calculations, duplicate Reward Point credits, duplicate reward redemptions, system or software malfunctions, technical synchronization errors, administrative mistakes, advertiser or survey provider reporting errors, payment or fulfillment processing errors, incorrect promotional bonuses, and display or account balance inaccuracies."},{t:"s",x:"11.3 Adjustments"},{t:"p",x:"Where an error is identified, View2Earn may take appropriate corrective action, including adding missing Reward Points, removing incorrectly awarded Reward Points, correcting account balances, cancelling duplicate rewards, reversing invalid transactions, reprocessing eligible redemption requests, correcting promotional rewards, and updating account records. Adjustments will be made only where reasonably necessary to maintain the integrity of the rewards program."},{t:"s",x:"11.4 Notification"},{t:"p",x:"Where appropriate and reasonably practicable, View2Earn may notify affected users of significant adjustments made to their Reward Point balance or redemption history. However, immediate corrections may be made without prior notice where necessary to prevent fraud or abuse, protect platform security, correct obvious system errors, or comply with legal or regulatory obligations."},{t:"s",x:"11.5 User Responsibility"},{t:"p",x:"Users should regularly review their Reward Point balances and redemption history. If a user believes an error has occurred, they should promptly contact View2Earn Support and provide any available information that may assist in the investigation. Failure to report known errors or knowingly benefiting from an obvious platform error may result in enforcement action under the Anti-Fraud Policy."},{t:"s",x:"11.6 Third-Party Errors"},{t:"p",x:"Some rewards and earning opportunities depend on advertisers, survey providers, payment providers, blockchain networks, or other third-party partners. View2Earn is not responsible for errors caused solely by third parties but will make reasonable efforts to investigate reported issues and, where appropriate, coordinate with the relevant partner to seek a resolution."},{t:"s",x:"11.7 Final Determination"},{t:"p",x:"View2Earn reserves the right to make the final determination regarding the existence of an error, the appropriate corrective action, and any resulting adjustment to Reward Points, rewards, or account balances. All decisions will be made in good faith, based on available evidence, applicable platform policies, contractual obligations, and relevant legal requirements."},{t:"h",x:"12. Taxes and Legal Compliance"},{t:"p",x:"Users are responsible for complying with all applicable laws, regulations, and tax obligations arising from their participation in the View2Earn rewards program. View2Earn is committed to operating its rewards program in accordance with applicable legal and regulatory requirements but does not provide tax, financial, accounting, or legal advice."},{t:"s",x:"12.1 User Tax Responsibility"},{t:"p",x:"Depending on a user's country or jurisdiction, rewards received through View2Earn may be subject to taxes, reporting requirements, or other legal obligations. Users are solely responsible for determining whether taxes apply to their rewards, reporting rewards to the appropriate tax authorities where required, paying any taxes/duties/fees/similar charges imposed by applicable law, and maintaining records required for tax or regulatory purposes. Users are encouraged to consult a qualified tax or legal advisor if they are uncertain about their obligations."},{t:"s",x:"12.2 Compliance with Applicable Laws"},{t:"p",x:"Users must use the Service in compliance with all applicable laws and regulations, including those relating to fraud prevention, financial crimes, anti-money laundering (AML), counter-terrorist financing (CTF), data protection and privacy, consumer protection, sanctions and trade restrictions, and digital assets and blockchain regulations (where applicable). Users must not use View2Earn for any unlawful, fraudulent, or prohibited purpose."},{t:"s",x:"12.3 Identity Verification and Compliance Checks"},{t:"p",x:"Where required by law, regulation, or risk assessment, View2Earn may require users to complete identity verification, account verification, or other compliance procedures before allowing participation in certain rewards, campaigns, or redemption activities. Failure to complete required verification may result in delays, restrictions, suspension, or denial of rewards."},{t:"s",x:"12.4 Regulatory Compliance"},{t:"p",x:"View2Earn reserves the right to delay, refuse, suspend, or cancel rewards, redemptions, or account activities where reasonably necessary to comply with applicable laws or regulations, respond to lawful requests from competent authorities, meet contractual obligations with business partners, protect the integrity and security of the platform, or prevent fraud, financial crime, or other unlawful activity."},{t:"s",x:"12.5 International Availability"},{t:"p",x:"The availability of rewards, campaigns, redemption methods, or platform features may vary by country or region due to legal, regulatory, operational, or commercial requirements. View2Earn reserves the right to limit or restrict access to certain rewards or services where required by applicable law or business considerations."},{t:"s",x:"12.6 No Professional Advice"},{t:"p",x:"Information provided by View2Earn regarding rewards, taxes, legal matters, or regulatory compliance is for general informational purposes only. Nothing in this Policy should be interpreted as legal, financial, investment, accounting, or tax advice. Users should seek independent professional advice regarding their individual circumstances."},{t:"s",x:"12.7 Reservation of Rights"},{t:"p",x:"View2Earn reserves the right to implement additional compliance measures, reporting requirements, or operational controls as necessary to comply with applicable laws, regulatory obligations, industry standards, or contractual commitments. Such measures may include additional verification, temporary restrictions, reporting obligations, or other reasonable actions designed to protect the platform, its users, advertisers, survey providers, business partners, and the broader View2Earn ecosystem."},{t:"h",x:"13. Changes to the Rewards Program"},{t:"p",x:"View2Earn continually develops and improves its rewards program to enhance the user experience, support business growth, comply with applicable laws, and maintain a fair, secure, and sustainable platform. Accordingly, View2Earn reserves the right to modify, suspend, replace, or discontinue any part of the rewards program at any time, subject to applicable law."},{t:"s",x:"13.1 Program Modifications"},{t:"p",x:"View2Earn may make changes to the rewards program, including but not limited to Reward Point earning rates, Reward Point redemption values, available rewards, redemption methods, promotional campaigns, bonus programs, referral incentives, eligibility requirements, verification procedures, processing times, participation requirements, and platform features related to rewards. These changes may be temporary or permanent."},{t:"s",x:"13.2 Reasons for Changes"},{t:"p",x:"Changes may be made for various reasons, including improving the rewards program, introducing new products or services, enhancing platform security, preventing fraud or abuse, responding to advertiser or business partner requirements, complying with legal or regulatory obligations, addressing technical or operational needs, reflecting market or economic conditions, and supporting the long-term sustainability of the View2Earn platform."},{t:"s",x:"13.3 User Notification"},{t:"p",x:"Where reasonably practicable, View2Earn will notify users of material changes to the rewards program through updates published on the View2Earn website, in-app notifications, email communications, official social media channels, or other communication methods deemed appropriate by View2Earn. Minor administrative, editorial, or technical updates may be made without individual notice."},{t:"s",x:"13.4 Effective Date of Changes"},{t:"p",x:"Unless otherwise required by applicable law, changes to the rewards program become effective on the date specified by View2Earn or, if no date is specified, upon publication through the Service or official communication channels. Users are encouraged to review updates regularly to remain informed about current program rules and requirements."},{t:"s",x:"13.5 Continued Participation"},{t:"p",x:"By continuing to access or use the Service after changes become effective, users acknowledge and accept the updated rewards program and agree to comply with the revised requirements. If a user does not agree with a material change, they may discontinue participation in the rewards program and, where applicable, close their account in accordance with the Terms of Service."},{t:"s",x:"13.6 No Guaranteed Continuation"},{t:"p",x:"View2Earn does not guarantee that any particular reward, campaign, promotion, bonus program, referral incentive, redemption option, Reward Point value, or platform feature will remain available indefinitely. View2Earn may discontinue or replace any aspect of the rewards program at its sole discretion, subject to applicable law."},{t:"s",x:"13.7 Reservation of Rights"},{t:"p",x:"Nothing in this Policy limits View2Earn's right to make operational, technical, legal, or commercial changes necessary to protect the integrity, security, compliance, or long-term sustainability of the rewards program. All changes will be implemented in good faith and in a manner that supports a fair and transparent experience for users while protecting the legitimate interests of View2Earn, its advertisers, survey providers, business partners, and the broader platform ecosystem."},{t:"h",x:"14. Limitation of Liability"},{t:"p",x:"To the fullest extent permitted by applicable law, View2Earn, its affiliates, directors, officers, employees, contractors, licensors, business partners, and service providers shall not be liable for any indirect, incidental, consequential, special, exemplary, or punitive damages arising out of or relating to the use of the Service, participation in the rewards program, or the redemption of rewards."},{t:"s",x:"14.1 No Guarantee of Rewards"},{t:"p",x:"View2Earn does not guarantee the availability of any specific task, survey, advertisement, campaign, or promotion; that every eligible activity will result in Reward Points; approval of every redemption request; continuous availability of the rewards program; or the availability of any specific reward or redemption option. Reward opportunities depend on advertiser demand, partner participation, verification outcomes, operational requirements, and other factors beyond our direct control."},{t:"s",x:"14.2 Third-Party Services"},{t:"p",x:"Certain features of the Service rely on third-party providers, including advertisers, survey providers, cloud hosting providers, payment processors, blockchain networks, and reward fulfillment partners. View2Earn is not responsible for delays, interruptions, errors, failures, or losses caused solely by the actions or omissions of these independent third parties."},{t:"s",x:"14.3 Technical Issues"},{t:"p",x:"View2Earn is not liable for losses resulting from internet connectivity problems, device malfunctions, software incompatibility, system maintenance, temporary service interruptions, technical failures beyond our reasonable control, blockchain network congestion or outages, or power failures or force majeure events. We will make reasonable efforts to restore affected services as quickly as practicable."},{t:"s",x:"14.4 Reward Delays"},{t:"p",x:"While View2Earn aims to process and deliver rewards promptly, we do not guarantee specific processing or delivery times. Delays may occur due to verification procedures, fraud prevention reviews, partner processing, legal requirements, technical issues, or circumstances beyond our reasonable control. Such delays do not, by themselves, constitute a breach of this Policy."},{t:"s",x:"14.5 User Responsibility"},{t:"p",x:"Users are responsible for providing accurate account and redemption information, maintaining the security of their accounts, complying with all applicable platform policies, meeting eligibility requirements, and reviewing reward details before submitting redemption requests. View2Earn is not responsible for losses resulting from inaccurate information provided by users or unauthorized access caused by a user's failure to protect their account credentials."},{t:"s",x:"14.6 Maximum Liability"},{t:"p",x:"To the maximum extent permitted by applicable law, View2Earn's total liability arising out of or relating to the rewards program shall not exceed the value of the specific Reward Points or reward that is the subject of the claim, unless a greater amount is required by applicable law. Nothing in this Policy excludes or limits liability that cannot be excluded or limited under applicable law."},{t:"s",x:"14.7 Reservation of Rights"},{t:"p",x:"Nothing in this section limits View2Earn's rights under the Terms of Service, Privacy Policy, Anti-Fraud Policy, or other applicable platform policies. View2Earn reserves all legal rights, remedies, and defenses available under applicable law to protect the Service, its users, advertisers, survey providers, business partners, and the long-term sustainability of the rewards program."},{t:"h",x:"15. Contact Information"},{t:"p",x:"View2Earn is committed to providing timely assistance regarding Reward Points, reward redemptions, account inquiries, and all matters relating to this Rewards & Redemption Policy. If you have any questions, require assistance, or wish to report an issue concerning your rewards, please contact us through the appropriate channel below."},{t:"l",x:["Reward Support: support@view2earn.org","Redemption Assistance: rewards@view2earn.org","Fraud Team: fraud@view2earn.org","Security Team: security@view2earn.org","Business & Partnership Inquiries: partners@view2earn.org","Legal & Compliance: legal@view2earn.org"]},{t:"p",x:"View2Earn will make reasonable efforts to acknowledge and respond to legitimate inquiries within a reasonable timeframe. Response times may vary depending on the complexity of the request, the availability of supporting information, and any verification or investigation that may be required."},{t:"p",x:"View2Earn appreciates your participation and remains committed to operating a fair, transparent, secure, and reliable rewards program for all users, advertisers, survey providers, merchants, and business partners."}]}};function s(e){return n[e]}}}]);